Voici un exemple de script Flask qui répond à vos exigences. Ce script utilise Flask pour créer une interface web avec un bouton pour lancer la copie des fichiers `.mp4` vers une clé USB montée sur `/media/usb`. Une barre de progression dynamique affiche l'avancement de la copie en pourcentage.

### Prérequis :
- Assurez-vous que Flask est installé (`pip install flask`).
- La clé USB doit être montée sur `/media/usb`.
- Les permissions doivent permettre la copie des fichiers vers la clé USB.

### Script Python (`app.py`) :

```python
from flask import Flask, render_template, jsonify
import os
import shutil
import threading

app = Flask(__name__)

# Configuration
SOURCE_DIR = '/chemin/vers/repertoire/source'  # Remplacez par le chemin de votre répertoire source
DEST_DIR = '/media/usb'

# Variables globales pour la progression
total_files = 0
copied_files = 0
lock = threading.Lock()
copy_in_progress = False

def copy_mp4_files():
    global total_files, copied_files, copy_in_progress
    copied_files = 0
    copy_in_progress = True

    # Compter le nombre total de fichiers .mp4
    total_files = sum(1 for f in os.listdir(SOURCE_DIR) if f.endswith('.mp4'))

    if total_files == 0:
        copy_in_progress = False
        return

    for filename in os.listdir(SOURCE_DIR):
        if filename.endswith('.mp4') and copy_in_progress:
            src_file = os.path.join(SOURCE_DIR, filename)
            dest_file = os.path.join(DEST_DIR, filename)
            try:
                shutil.copy2(src_file, dest_file)
                with lock:
                    copied_files += 1
            except Exception as e:
                print(f"Erreur lors de la copie de {filename}: {e}")

    copy_in_progress = False

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/start_copy', methods=['POST'])
def start_copy():
    global copy_in_progress
    if not copy_in_progress:
        threading.Thread(target=copy_mp4_files).start()
    return jsonify({'status': 'started'})

@app.route('/progress')
def progress():
    global total_files, copied_files
    if total_files == 0:
        return jsonify({'progress': 0, 'complete': False})
    progress_percent = (copied_files / total_files) * 100
    complete = copied_files == total_files
    return jsonify({'progress': progress_percent, 'complete': complete})

if __name__ == '__main__':
    app.run(debug=True)
