To solve this problem using heaps, we can model it as a graph where each station and the final depth are nodes. We can then use a priority queue (min-heap) to find the minimum total time required to reach the final depth without running out of oxygen. Here's a step-by-step explanation of the logic and the corresponding C code.

### Logic:
1. **Graph Representation**:
   - Treat each station and the final depth as nodes in a graph.
   - The edge between two nodes represents the oxygen consumption and the time taken to refill at stations.

2. **Priority Queue (Min-Heap)**:
   - Use a min-heap to always explore the path with the minimum refilling time first.
   - Each element in the heap stores the current depth, remaining oxygen, total time spent refilling, and the list of stations used so far.

3. **Exploration**:
   - Start from the surface (depth 0) with the initial oxygen supply.
   - At each step, decide whether to proceed to the next station or to the final depth, ensuring oxygen is not depleted.
   - If a station is used, add the refilling time to the total time and update the oxygen supply.

4. **Termination**:
   - If the final depth is reached, return the total refilling time.
   - If it’s impossible to reach the final depth, return `-1` along with the maximum depth reachable.

### C Code Implementation:

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define MAX_STATIONS 1000

typedef struct {
    int depth;
    int oxygen;
    int time;
    int stations_used[MAX_STATIONS];
    int count;
} State;

int compare(const void *a, const void *b) {
    return ((State *)a)->time - ((State *)b)->time;
}

int main() {
    int n, initial_oxygen, final_depth, oxygen_refill;
    scanf("%d %d %d %d", &n, &initial_oxygen, &final_depth, &oxygen_refill);

    int depths[MAX_STATIONS], times[MAX_STATIONS];
    for (int i = 0; i < n; i++) scanf("%d", &depths[i]);
    for (int i = 0; i < n; i++) scanf("%d", &times[i]);

    State heap[MAX_STATIONS];
    int heap_size = 0;

    State initial_state = {0, initial_oxygen, 0, {0}, 0};
    heap[heap_size++] = initial_state;

    int min_time = INT_MAX;
    int max_reachable_depth = 0;

    while (heap_size > 0) {
        State current = heap[0];
        for (int i = 0; i < heap_size - 1; i++) heap[i] = heap[i + 1];
        heap_size--;

        if (current.depth == final_depth) {
            if (current.time < min_time) {
                min_time = current.time;
            }
            continue;
        }

        max_reachable_depth = current.depth > max_reachable_depth ? current.depth : max_reachable_depth;

        if (current.depth >= final_depth) continue;

        for (int i = 0; i < n; i++) {
            if (depths[i] > current.depth && current.oxygen >= (depths[i] - current.depth)) {
                int new_oxygen = current.oxygen - (depths[i] - current.depth) + oxygen_refill;
                if (new_oxygen >= 0) {
                    State new_state = {depths[i], new_oxygen, current.time + times[i], {0}, 0};
                    for (int j = 0; j < current.count; j++) {
                        new_state.stations_used[j] = current.stations_used[j];
                    }
                    new_state.stations_used[current.count] = i;
                    new_state.count = current.count + 1;
                    heap[heap_size++] = new_state;
                    qsort(heap, heap_size, sizeof(State), compare);
                }
            }
        }

        State new_state = {current.depth + 1, current.oxygen - 1, current.time, {0}, 0};
        if (new_state.oxygen >= 0) {
            for (int j = 0; j < current.count; j++) {
                new_state.stations_used[j] = current.stations_used[j];
            }
            new_state.count = current.count;
            heap[heap_size++] = new_state;
            qsort(heap, heap_size, sizeof(State), compare);
        }
    }

    if (min_time != INT_MAX) {
        printf("%d\n", min_time);
    } else {
        printf("-1 %d\n", max_reachable_depth);
    }

    return 0;
}
```

### Explanation of the Code:
1. **State Structure**:
   - Represents the current state of Percy, including depth, remaining oxygen, total time spent, and stations used.

2. **Heap Implementation**:
   - A simple array-based heap is used, sorted using `qsort` after each insertion to maintain the min-heap property.

3. **Exploration**:
   - The algorithm explores all possible paths by either moving to the next depth or using a station to refill oxygen.
   - If a station is used, the oxygen is refilled, and the time is updated.

4. **Termination**:
   - If the final depth is reached, the minimum time is updated.
   - If the heap is exhausted without reaching the final depth, the maximum reachable depth is returned along with `-1`.

This approach ensures that the solution is both efficient and easy to understand, leveraging the properties of heaps to prioritize paths with minimal refilling time.

