下面是一个用C语言实现的简单银行家算法的示例。这个程序模拟了操作系统中的资源分配和进程调度，使用了银行家算法来避免死锁。程序中包含进程控制块（PCB）、资源分配、进程调度以及状态输出等功能。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROCESSES 5
#define MAX_RESOURCES 3
#define TIME_QUANTUM 1

typedef enum { W, R, B, F } ProcessState;

typedef struct {
    char name[10];
    int max[MAX_RESOURCES];    // 最大需求
    int allocated[MAX_RESOURCES]; // 已分配资源
    int need[MAX_RESOURCES];   // 还需要的资源
    ProcessState state;
} PCB;

int available[MAX_RESOURCES] = {10, 15, 8}; // 可用资源
PCB processes[MAX_PROCESSES];
int current_process = -1;
int completed_processes = 0;

void initialize_processes() {
    srand(time(NULL));
    for (int i = 0; i < MAX_PROCESSES; i++) {
        sprintf(processes[i].name, "P%d", i + 1);
        processes[i].state = W;
        for (int j = 0; j < MAX_RESOURCES; j++) {
            processes[i].max[j] = rand() % 5 + 1; // 随机生成最大需求
            processes[i].allocated[j] = 0;
            processes[i].need[j] = processes[i].max[j];
        }
    }
}

int is_safe_state(int request[], int process_id) {
    int work[MAX_RESOURCES];
    memcpy(work, available, sizeof(available));

    PCB finish[MAX_PROCESSES];
    int finish_count = 0;

    while (1) {
        int found = 0;
        for (int i = 0; i < MAX_PROCESSES; i++) {
            if (processes[i].state == W || processes[i].state == B) {
                int can_allocate = 1;
                for (int j = 0; j < MAX_RESOURCES; j++) {
                    if (processes[i].need[j] > work[j]) {
                        can_allocate = 0;
                        break;
                    }
                }
                if (can_allocate) {
                    for (int j = 0; j < MAX_RESOURCES; j++) {
                        work[j] += processes[i].allocated[j];
                    }
                    memcpy(finish[finish_count].allocated, processes[i].allocated, sizeof(processes[i].allocated));
                    finish[finish_count].state = processes[i].state;
                    finish_count++;
                    processes[i].state = F;
                    found = 1;
                }
            }
        }
        if (!found) break;
    }

    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state != F) return 0;
    }
    return 1;
}

void request_resources(int process_id, int request[]) {
    if (processes[process_id].state != R) return;

    int safe = 1;
    for (int i = 0; i < MAX_RESOURCES; i++) {
        if (request[i] > processes[process_id].need[i] || request[i] > available[i]) {
            safe = 0;
            break;
        }
    }

    if (safe && is_safe_state(request, process_id)) {
        for (int i = 0; i < MAX_RESOURCES; i++) {
            available[i] -= request[i];
            processes[process_id].allocated[i] += request[i];
            processes[process_id].need[i] -= request[i];
        }
        if (processes[process_id].need[0] == 0 && processes[process_id].need[1] == 0 && processes[process_id].need[2] == 0) {
            processes[process_id].state = F;
            completed_processes++;
        }
    } else {
        processes[process_id].state = B;
    }
}

void print_system_state() {
    printf("Current Process: %s\n", current_process == -1 ? "None" : processes[current_process].name);
    printf("Ready Queue: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == W) printf("%s ", processes[i].name);
    }
    printf("\nBlocked Queue: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == B) printf("%s ", processes[i].name);
    }
    printf("\nCompleted Processes: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == F) printf("%s ", processes[i].name);
    }
    printf("\nPCB Information:\n");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        printf("Process %s: Allocated [%d, %d, %d], Need [%d, %d, %d], State %c\n",
               processes[i].name,
               processes[i].allocated[0], processes[i].allocated[1], processes[i].allocated[2],
               processes[i].need[0], processes[i].need[1], processes[i].need[2],
               processes[i].state);
    }
    printf("Available Resources: [%d, %d, %d]\n\n", available[0], available[1], available[2]);
}

void scheduler() {
    static int time_elapsed = 0;
    if (current_process != -1 && time_elapsed < TIME_QUANTUM) {
        int request[MAX_RESOURCES] = {rand() % 3, rand() % 3, rand() % 3}; // 随机生成资源请求
        request_resources(current_process, request);
        time_elapsed++;
    } else {
        time_elapsed = 0;
        current_process = (current_process + 1) % MAX_PROCESSES;
        while (processes[current_process].state == F && completed_processes < MAX_PROCESSES) {
            current_process = (current_process + 1) % MAX_PROCESSES;
        }
        if (processes[current_process].state != F) {
            processes[current_process].state = R;
        }
    }
}

int main() {
    initialize_processes();
    while (completed_processes < MAX_PROCESSES) {
        scheduler();
        print_system_state();
    }
    return 0;
}
```

### 代码说明：
1. **PCB结构体**：每个进程由一个PCB表示，包含进程名、最大需求、已分配资源、还需要的资源以及进程状态。
2. **初始化**：`initialize_processes`函数随机生成每个进程的最大资源需求。
3. **银行家算法**：`is_safe_state`函数检查当前状态是否安全，即是否存在一个进程调度顺序可以使所有进程完成。
4. **资源请求**：`request_resources`函数处理进程的资源请求，并根据银行家算法判断是否可以分配资源。
5. **调度器**：`scheduler`函数模拟时间片轮转调度，每个进程运行一个时间片后切换到下一个进程。
6. **状态输出**：`print_system_state`函数输出当前系统的状态，包括正在运行的进程、就绪队列、阻塞队列、完成的进程以及每个进程的PCB信息。

### 运行效果：
程序会模拟多个进程的资源请求和调度，并输出每次调度后的系统状态。当所有进程完成后，程序结束。

### 注意事项：
- 程序中的资源请求是随机生成的，实际应用中可能需要根据具体场景调整。
- 银行家算法的实现是简化的，实际操作系统中可能需要更复杂的处理。

这个程序可以作为理解银行家算法和进程调度的一个基础示例。

