    if (list->count >= MAX_TASKS) {
        printf("Error: Task list is full.\n");
        return;
    }

    printf("Enter the task: ");
    fgets(list->tasks[list->count], MAX_TASK_LENGTH, stdin);
    list->tasks[list->count][strcspn(list->tasks[list->count], "\n")] = 0; // Remove newline character
    list->count++;
    printf("Task added successfully!\n");
}

void viewTasks(ToDoList *list) {
    if (list->count == 0) {
        printf("No tasks in the list.\n");
        return;
    }

    printf("\n--- Tasks ---\n");
    for (int i = 0; i < list->count; i++) {
        printf("%d. %s\n", i + 1, list->tasks[i]);
    }
}

void deleteTask(ToDoList *list) {
    if (list->count == 0) {
        printf("No tasks to delete.\n");
        return;
    }

    viewTasks(list);
    printf("Enter the task number to delete: ");
    int taskNumber;
    scanf("%d", &taskNumber);

    if (taskNumber < 1 || taskNumber > list->count) {
        printf("Invalid task number.\n");
        return;
    }

    for (int i = taskNumber - 1; i < list->count - 1; i++) {
        strcpy(list->tasks[i], list->tasks[i + 1]);
    }
    list->count--;
    printf("Task deleted successfully!\n");

    // Clear the input buffer
    int c;
    while ((c = getchar()) != '\n' && c != EOF);
}

int main() {
