    list.count = 0;

    int choice;
    while (1) {
        displayMenu();
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                addTask(&list);
                break;
            case 2:
                viewTasks(&list);
                break;
            case 3:
                deleteTask(&list);
                break;
            case 4:
                printf("Exiting the ToDo List application.\n");
