        int isUnique = 1;  // Flag to check if the number is unique
        for (j = 0; j < uniqueCount; j++) {
            if (numbers[i] == unique[j]) {
                repetitionCount[j]++;  // Increment repetition count
                isUnique = 0;
                break;
