### Программа на C

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

void get_mac_address(unsigned char *mac) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ - 1);

    if (ioctl(sock, SIOCGIFHWADDR, &ifr) < 0) {
        perror("Failed to get MAC address");
        close(sock);
        exit(EXIT_FAILURE);
    }

    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
    close(sock);
}

void generate_unique_id(unsigned char *mac, char *unique_id) {
    unsigned char hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char *)mac, 6, hash);

    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(unique_id + (i * 2), "%02x", hash[i]);
    }
    unique_id[MD5_DIGEST_LENGTH * 2] = '\0';
}

int main() {
    unsigned char mac[6];
    char unique_id[33];

    get_mac_address(mac);
    generate_unique_id(mac, unique_id);

    printf("Уникальный номер платы: %s\n", unique_id);

    return 0;
}
```

