#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

#define INF 32767

typedef struct Edge {
    int u, v, w;
} Edge;

int compare(const void *a, const void *b) {
    return ((Edge *)a)->w - ((Edge *)b)->w;
}

int find(int *parent, int i) {
    if (parent[i] != i) {
        parent[i] = find(parent, parent[i]);
    }
    return parent[i];
}

void unionSets(int *parent, int *rank, int x, int y) {
    int xroot = find(parent, x);
    int yroot = find(parent, y);

    if (rank[xroot] < rank[yroot]) {
        parent[xroot] = yroot;
    } else if (rank[xroot] > rank[yroot]) {
        parent[yroot] = xroot;
    } else {
        parent[yroot] = xroot;
        rank[xroot]++;
    }
}

void Kruskal(int n, int e, int **edges, int *edgeCount) {
    Edge *edgeList = (Edge *)malloc(e * sizeof(Edge));
    int index = 0;

    // 构建边表
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (edges[i][j] != INF) {
                edgeList[index].u = i;
                edgeList[index].v = j;
                edgeList[index].w = edges[i][j];
                index++;
            }
        }
    }

    // 排序边表
    qsort(edgeList, index, sizeof(Edge), compare);

    int *parent = (int *)malloc(n * sizeof(int));
    int *rank = (int *)malloc(n * sizeof(int));

    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    printf("Krusal:\n");
    int edge_count = 0;
    for (int i = 0; i < index && edge_count < n - 1; i++) {
        int u = edgeList[i].u;
        int v = edgeList[i].v;
        int w = edgeList[i].w;

        int setU = find(parent, u);
        int setV = find(parent, v);

        if (setU != setV) {
            printf("(%d,%d):%d\n", u, v, w);
            unionSets(parent, rank, setU, setV);
            edge_count++;
        }
    }

    free(edgeList);
    free(parent);
    free(rank);
}

int main() {
