```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define PORT 2346
#define BUFFER_SIZE 256
#define MAX_ENTRIES 100

struct Entry {
    char ip[INET_ADDRSTRLEN];
    int port;
};

struct Entry tb[MAX_ENTRIES];
int tb_index = 0;

void handle_sigalrm(int sig) {
    printf("Tableau tb:\n");
    for (int i = 0; i < tb_index; i++) {
        printf("IP: %s, Port: %d\n", tb[i].ip, tb[i].port);
    }
    alarm(30); // Réinitialise l'alarme pour les 30 prochaines secondes
}

void sender_process(char *message) {
    int sockfd;
    struct sockaddr_in broadcast_addr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Erreur lors de la création du socket");
        exit(EXIT_FAILURE);
    }

    int broadcast = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &broadcast, sizeof(broadcast)) < 0) {
        perror("Erreur lors de la configuration du socket en mode broadcast");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = INADDR_BROADCAST;
    broadcast_addr.sin_port = htons(PORT);

    signal(SIGALRM, handle_sigalrm);
    alarm(30); // Première alarme pour afficher le tableau dans 30 secondes

    while (1) {
        if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
            perror("Erreur lors de l'envoi du message");
        }
        sleep(1); // Envoie toutes les secondes
    }

    close(sockfd);
}

void receiver_process(char *expected_message) {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Erreur lors de la création du socket");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Erreur lors du bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int n = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &client_len);
        if (n < 0) {
            perror("Erreur lors de la réception du message");
            continue;
        }

        buffer[n] = '\0';
        if (strcmp(buffer, expected_message) == 0) {
            if (tb_index < MAX_ENTRIES) {
                inet_ntop(AF_INET, &(client_addr.sin_addr), tb[tb_index].ip, INET_ADDRSTRLEN);
                tb[tb_index].port = ntohs(client_addr.sin_port);
                tb_index++;
            }
        }
    }

    close(sockfd);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <message>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();

    if (pid < 0) {
        perror("Erreur lors du fork");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Processus fils (récepteur)
        receiver_process(argv[1]);
    } else {
        // Processus père (émetteur)
        sender_process(argv[1]);
    }

    return 0;
}
```

### Explications :

1. **Structure `Entry`** : Stocke l'adresse IP et le port des expéditeurs.
2. **Gestion des signaux** : Le signal `SIGALRM` est utilisé pour afficher le tableau `tb` toutes les 30 secondes.
3. **Processus émetteur** : Envoie le message passé en argument toutes les secondes à l'adresse de broadcast `255.255.255.255` sur le port `2346`.
4. **Processus récepteur** : Attend des messages sur le port `2346`. Si un message reçu correspond à celui passé en argument, il stocke l'adresse IP et le port de l'expéditeur dans le tableau `tb`.
5. **Fork** : Le programme crée deux processus : un pour l'envoi et un pour la réception.

### Compilation et exécution :
