    char line[MAX_LINE_LENGTH];
    Node* current_function = NULL;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char* token = strtok(line, " ()\n");
        if (token == NULL) continue;

        if (strchr(token, '(') != NULL) {
            // Это определение функции
            char function_name[MAX_FUNCTION_NAME_LENGTH];
            sscanf(token, "%s", function_name);

            Node* new_node = create_node(function_name);
            if (*root == NULL) {
                *root = new_node;
            } else {
                add_child(current_function, new_node);
            }
            current_function = new_node;
        } else if (isalpha(token[0])) {
            // Это вызов функции
            Node* new_node = create_node(token);
            add_child(current_function, new_node);
        }
    }

    fclose(file);
}

int main() {
    Node* root = NULL;
    parse_file("test.txt", &root);
    print_tree(root, 0);

    // Освобождение памяти (для полноты, но в этом примере не реализовано)
