```c
#include <stdio.h>
#include <stdlib.h>

// Hàm kiểm tra số đối xứng
int isPalindrome(int num) {
    int original = num;
    int reversed = 0;

    while (num > 0) {
        reversed = reversed * 10 + num % 10;
        num /= 10;
    }

    return original == reversed;
}

int main() {
    int n, sum = 0, count = 0;

    // Nhập số lượng số
    printf("Nhập số lượng số: ");
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        int num;
        printf("Nhập số thứ %d: ", i + 1);
        scanf("%d", &num);

        // Kiểm tra và tính tổng các số đối xứng
        if (isPalindrome(num)) {
            sum += num;
            count++;
        }
    }

    // Tính và hiển thị trung bình
    if (count > 0) {
        double average = (double)sum / count;
        printf("Trung bình các số đối xứng là: %.2f\n", average);
    } else {
        printf("Không có số đối xứng nào được nhập.\n");
    }

    return 0;
}
```

