در زیر کد C را برای حل این مسئله ارائه می‌دهم:

```c
#include <stdio.h>
#include <string.h>

int manacher(const char *s, int n) {
    char t[2 * n + 1];
    int p[2 * n + 1];
    int center = 0, right = 0;

    // تبدیل رشته به فرمت مورد نیاز Manacher
    for (int i = 0; i < n; i++) {
        t[2 * i + 1] = s[i];
        t[2 * i + 2] = '#';
    }
    t[0] = '#';
    t[2 * n + 1] = '\0';

    // اجرای الگوریتم Manacher
    for (int i = 1; i <= 2 * n; i++) {
        if (i < right) {
            p[i] = p[2 * center - i] < right - i ? p[2 * center - i] : right - i;
        } else {
            p[i] = 0;
        }

        // گسترش محدوده Palindrome
        while (t[i + p[i] + 1] == t[i - p[i] - 1] && i + p[i] + 1 < 2 * n + 1) {
            p[i]++;
        }

        // به‌روزرسانی مرکز و محدوده راست
        if (i + p[i] > right) {
            center = i;
            right = i + p[i];
        }
    }

    // پیدا کردن بزرگترین Palindrome
    int max_len = 0;
    for (int i = 1; i <= 2 * n; i++) {
        if (p[i] > max_len) {
            max_len = p[i];
        }
    }

    return max_len;
}

int main() {
    char s[1001];
    scanf("%s", s);
    int n = strlen(s);

    // طول بزرگترین زیررشته متقارن
    int result = manacher(s, n);

    // چون در Manacher طول Palindrome دو برابر است (به دلیل کاراکترهای #)
    printf("%d\n", result);

    return 0;
}
```

