         const uint32_t *ptr = (const uint32_t *)data;
         const size_t count = len / 4;
         for (size_t i = 0; i < count; i++) {
             if (ptr[i] != 0xFFFFFFFF) {
                 return false;
             }
         }
         // 检查剩余字节（如果存在）
         const uint8_t *remainder = (const uint8_t *)(ptr + count);
         for (size_t i = 0; i < len % 4; i++) {
             if (remainder[i] != 0xFF) {
