            } else if (variazione > 0 && magazzino[i].quantita + variazione > 10000) {
                return -2; // Incremento non realizzabile
            } else {
                printf("Variazione di %d per il prodotto %s\n", variazione, codice);
                return 1; // Variazione realizzabile
            }
        }
    }
    return -1; // Prodotto non trovato
}

void aggiorna_magazzino(Prodotto *magazzino, int n_prodotti, const char *codice, int variazione) {
    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            float valore_prima = calcola_valore_magazzino(magazzino, n_prodotti);
            magazzino[i].quantita += variazione;
            float valore_dopo = calcola_valore_magazzino(magazzino, n_prodotti);
