            printf("Valore magazzino dopo: %.2f€\n", valore_dopo);
            return;
        }
    }
}

float calcola_valore_magazzino(Prodotto *magazzino, int n_prodotti) {
    float valore = 0.0;
    for (int i = 0; i < n_prodotti; i++) {
        valore += magazzino[i].costo * magazzino[i].quantita;
    }
    return valore;
}

void stampa_magazzino_ordinato(FILE *file, Prodotto *magazzino, int n_prodotti) {
    // Crea un vettore di indici per l'ordinamento
    int *indici = malloc(n_prodotti * sizeof(int));
    for (int i = 0; i < n_prodotti; i++) {
        indici[i] = i;
    }

    // Ordina gli indici in base al valore decrescente
    for (int i = 0; i < n_prodotti; i++) {
        for (int j = i + 1; j < n_prodotti; j++) {
            float valore_i = magazzino[indici[i]].costo * magazzino[indici[i]].quantita;
            float valore_j = magazzino[indici[j]].costo * magazzino[indici[j]].quantita;
            if (valore_i < valore_j) {
                int temp = indici[i];
                indici[i] = indici[j];
                indici[j] = temp;
            }
        }
    }

    // Stampa il magazzino ordinato
    for (int i = 0; i < n_prodotti; i++) {
        fprintf(file, "%s %.2f %d\n", magazzino[indici[i]].codice, magazzino[indici[i]].costo, magazzino[indici[i]].quantita);
    }

    free(indici);
}
