```c
#include <stdio.h>
#include <stdlib.h>

// 定义二叉树节点结构体
typedef struct TreeNode {
    int val;
    struct TreeNode *left;
    struct TreeNode *right;
} TreeNode;

// 创建新节点
TreeNode* newNode(int val) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    node->val = val;
    node->left = NULL;
    node->right = NULL;
    return node;
}

// 构建二叉树
TreeNode* buildTree(int n, int* left, int* right) {
    TreeNode* nodes[n + 1];
    for (int i = 1; i <= n; i++) {
        nodes[i] = newNode(i);
    }

    for (int i = 1; i <= n; i++) {
        if (left[i - 1] != -1) {
            nodes[i]->left = nodes[left[i - 1]];
        }
        if (right[i - 1] != -1) {
            nodes[i]->right = nodes[right[i - 1]];
        }
    }

    return nodes[1]; // 返回根节点
}

// 先序遍历
void preOrder(TreeNode* root, int* result, int* index) {
    if (root == NULL) return;
    result[(*index)++] = root->val;
    preOrder(root->left, result, index);
    preOrder(root->right, result, index);
}

// 中序遍历
void inOrder(TreeNode* root, int* result, int* index) {
    if (root == NULL) return;
    inOrder(root->left, result, index);
    result[(*index)++] = root->val;
    inOrder(root->right, result, index);
}

// 后序遍历
void postOrder(TreeNode* root, int* result, int* index) {
    if (root == NULL) return;
    postOrder(root->left, result, index);
    postOrder(root->right, result, index);
    result[(*index)++] = root->val;
}

// 打印遍历结果
void printTraversal(int* result, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d", result[i]);
        if (i < size - 1) printf(" ");
    }
    printf("\n");
}

int main() {
    int n;
    scanf("%d", &n);

    int left[n], right[n];
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &i, &left[i], &right[i]);
    }

    TreeNode* root = buildTree(n, left, right);

    int* preResult = (int*)malloc(n * sizeof(int));
    int* inResult = (int*)malloc(n * sizeof(int));
    int* postResult = (int*)malloc(n * sizeof(int));

    int preIndex = 0, inIndex = 0, postIndex = 0;

    preOrder(root, preResult, &preIndex);
    inOrder(root, inResult, &inIndex);
    postOrder(root, postResult, &postIndex);

    printTraversal(preResult, n);
    printTraversal(inResult, n);
    printTraversal(postResult, n);

    free(preResult);
    free(inResult);
    free(postResult);

    return 0;
}
