#include <arpa/inet.h>
#include <net/if.h>
#include <ifaddrs.h>
#include <unistd.h>
#include <errno.h>

#define MAX_ID_LENGTH 18  // MAC-адрес в формате XX:XX:XX:XX:XX:XX

void generate_device_id(char *id) {
    struct ifaddrs *ifaddr, *ifa;
    int family, s;
    char host[NI_MAXHOST];

    if (getifaddrs(&ifaddr) == -1) {
        perror("getifaddrs");
        exit(EXIT_FAILURE);
    }

    for (ifa = ifaddr; ifa != NULL; ifa = ifa->ifa_next) {
        if (ifa->ifa_addr == NULL) continue;

        family = ifa->ifa_addr->sa_family;

        if (family == AF_PACKET) {
            s = getnameinfo(ifa->ifa_addr, sizeof(struct sockaddr_ll), host, NI_MAXHOST, NULL, 0, NI_NUMERICSCOPE);
            if (s != 0) {
                fprintf(stderr, "getnameinfo() failed: %s\n", gai_strerror(s));
                continue;
            }

            // Используем первый найденный MAC-адрес
            snprintf(id, MAX_ID_LENGTH, "%s", host);
            break;
        }
    }

    freeifaddrs(ifaddr);

    // Если MAC-адрес не найден, генерируем случайный идентификатор (для примера)
    if (id[0] == '\0') {
        snprintf(id, MAX_ID_LENGTH, "00:00:00:00:00:00");
    }
}

