    int carry = 0;
    int len_a = strlen(a);
    int len_b = strlen(b);
    int max_len = (len_a > len_b) ? len_a : len_b;

    for (int i = 0; i <= max_len; ++i) {
        int digit_a = (i < len_a) ? a[len_a - 1 - i] - '0' : 0;
        int digit_b = (i < len_b) ? b[len_b - 1 - i] - '0' : 0;

        int sum = digit_a + digit_b + carry;
        carry = sum / 10;
        result[max_len - i] = (sum % 10) + '0';
    }

    result[max_len + 1] = '\0';
}

// Функция для вычитания двух чисел
void subtract(char a[], char b[], char result[]) {
    int len_a = strlen(a);
    int len_b = strlen(b);
    int borrow = 0;

    for (int i = 0; i < len_a; ++i) {
        int digit_a = a[len_a - 1 - i] - '0';
        int digit_b = (i < len_b) ? b[len_b - 1 - i] - '0' : 0;

        int diff = digit_a - digit_b - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }

        result[len_a - 1 - i] = diff + '0';
    }

    // Удаление ведущих нулей
    int start = 0;
    while (result[start] == '0' && start < len_a - 1) {
        start++;
    }

    if (start == len_a - 1 && result[start] == '0') {
        result[0] = '0';
        result[1] = '\0';
    } else {
        memmove(result, result + start, len_a - start + 1);
    }
}

