    int len_b = strlen(b);
    char temp[MAX_DIGITS] = {0};

    for (int i = 0; i < len_a; ++i) {
        int carry = 0;
        for (int j = 0; j < len_b; ++j) {
            int digit_a = a[len_a - 1 - i] - '0';
            int digit_b = b[len_b - 1 - j] - '0';
            int product = digit_a * digit_b + carry + (temp[i + j] - '0');

            carry = product / 10;
            temp[i + j] = (product % 10) + '0';
        }
        temp[i + len_b] = carry + '0';
    }

    // Удаление ведущих нулей
    int start = 0;
    while (temp[start] == '0' && start < len_a + len_b - 1) {
        start++;
    }

    if (start == len_a + len_b - 1 && temp[start] == '0') {
