using namespace std;

// Function to check if a number is a power of 2
bool isPowerOfTwo(int n) {
    return (n != 0) && ((n & (n - 1)) == 0);
}

// Function to tile the board with trominoes
void tromino(int x_board, int y_board, int x_missing, int y_missing, int board_size, vector<vector<string>>& board) {
    if (board_size == 2) {
        // Base case: board_size is 2
        int dx = x_missing - x_board;
        int dy = y_missing - y_board;

        if (dx == 0 && dy == 1) { // Missing square is in the upper left corner
            board[0][0] = "MS";
            board[0][1] = "LR";
            board[1][0] = "LR";
            board[1][1] = "LR";
        } else if (dx == 1 && dy == 1) { // Missing square is in the upper right corner
            board[0][0] = "LL";
            board[0][1] = "MS";
            board[1][0] = "LL";
            board[1][1] = "LL";
        } else if (dx == 1 && dy == 0) { // Missing square is in the lower right corner
            board[0][0] = "UL";
            board[0][1] = "UL";
            board[1][0] = "UL";
            board[1][1] = "MS";
        } else if (dx == 0 && dy == 0) { // Missing square is in the lower left corner
            board[0][0] = "UR";
            board[0][1] = "UR";
            board[1][0] = "MS";
            board[1][1] = "UR";
        }
        return;
    }

    // Divide the board into four subboards
    int half_size = board_size / 2;

    // Determine which subboard contains the missing square
    int x_upper_left = (x_missing < x_board + half_size) ? x_missing : x_board + half_size;
    int y_upper_left = (y_missing >= y_board + half_size) ? y_missing : y_board + half_size;

    int x_upper_right = (x_missing >= x_board + half_size) ? x_missing : x_board + half_size;
    int y_upper_right = (y_missing >= y_board + half_size) ? y_missing : y_board + half_size;

    int x_lower_left = (x_missing < x_board + half_size) ? x_missing : x_board + half_size;
    int y_lower_left = (y_missing < y_board + half_size) ? y_missing : y_board + half_size;

    int x_lower_right = (x_missing >= x_board + half_size) ? x_missing : x_board + half_size;
    int y_lower_right = (y_missing < y_board + half_size) ? y_missing : y_board + half_size;

    // Recursive calls for the four subboards
    tromino(x_board, y_board + half_size, x_upper_left, y_upper_left, half_size, board);
    tromino(x_board + half_size, y_board + half_size, x_upper_right, y_upper_right, half_size, board);
    tromino(x_board, y_board, x_lower_left, y_lower_left, half_size, board);
    tromino(x_board + half_size, y_board, x_lower_right, y_lower_right, half_size, board);
}

