int update_data_item() {
    double rand_val = (double)rand() / RAND_MAX;
    if (rand_val < HOT_DATA_UPDATE_PROB) {
        int data_item_id = HOT_DATA_START + rand() % (HOT_DATA_END - HOT_DATA_START + 1);
        server_db[data_item_id - 1].last_update_time = current_time;
