            // Cache hit, send check message to server
            if (client_caches[client_id].cache[i].timestamp >= server_db[data_item_id - 1].last_update_time) {
                cache_hit = 1;
                query_delay = 1; // Assume minimal delay for confirmation
            } else {
                // Cache miss due to invalidation
                cache_hit = 0;
                query_delay = (DATA_ITEM_SIZE * 8) / BANDWIDTH; // Transmission delay
            }
            break;
        }
    }

    if (!cache_hit) {
        // Cache miss, send request message to server
        query_delay = (DATA_ITEM_SIZE * 8) / BANDWIDTH; // Transmission delay

        // Update cache using LRU
        int lru_index = client_caches[client_id].lru_index;
        client_caches[client_id].cache[lru_index].data_item_id = data_item_id;
        client_caches[client_id].cache[lru_index].timestamp = current_time;
        client_caches[client_id].lru_index = (lru_index + 1) % CACHE_SIZE;
    }

    // Update statistics
    query_count++;
    if (cache_hit) cache_hit_count++;
    total_query_delay += query_delay;
}

void simulate(int T_query, int T_update, int num_iterations) {
    init_server_db();
    init_client_caches();
    query_count = 0;
    cache_hit_count = 0;
    total_query_delay = 0;

    for (int iter = 0; iter < num_iterations; iter++) {
        // Generate queries
        if (current_time % T_query == 0) {
            for (int client_id = 0; client_id < NUM_CLIENTS; client_id++) {
                int data_item_id = generate_data_item_query();
                handle_query(client_id, data_item_id);
            }
        }

        // Generate updates
        if (current_time % T_update == 0) {
            update_data_item();
        }

        current_time++;
    }
}

void print_results() {
    double cache_hit_ratio = (double)cache_hit_count / query_count;
    double avg_query_delay = (double)total_query_delay / query_count;
    printf("Cache Hit Ratio: %.4f\n", cache_hit_ratio);
    printf("Average Query Delay: %.4f seconds\n", avg_query_delay);
}

int main() {
