```cpp
#include <algorithm>
#include <climits>
#include <iostream>
#include <queue>
#include <vector>

using namespace std;

typedef pair<int, int> pii;

const int INF = INT_MAX;

void dijkstra(int start, vector<vector<pii>> &graph, vector<int> &dist) {
  priority_queue<pii, vector<pii>, greater<pii>> pq;
  pq.push({0, start});
  dist[start] = 0;

  while (!pq.empty()) {
    int u = pq.top().second;
    int d = pq.top().first;
    pq.pop();

    if (d > dist[u])
      continue;

    for (auto &edge : graph[u]) {
      int v = edge.first;
      int w = edge.second;

      if (dist[v] > dist[u] + w) {
        dist[v] = dist[u] + w;
        pq.push({dist[v], v});
      }
    }
  }
}

int main() {
  int n, m, k;
  cin >> n >> m >> k;

  vector<vector<pii>> graph(n + 1);
  vector<int> fiberLatencies(k);
  vector<int> fiberNodes(k);

  for (int i = 0; i < m; ++i) {
    int a, b, l;
    cin >> a >> b >> l;
    graph[a].push_back({b, l});
    graph[b].push_back({a, l});
  }

  for (int i = 0; i < k; ++i) {
    cin >> fiberNodes[i] >> fiberLatencies[i];
    graph[1].push_back({fiberNodes[i], fiberLatencies[i]});
    graph[fiberNodes[i]].push_back({1, fiberLatencies[i]});
  }

  vector<int> originalDist(n + 1, INF);
  dijkstra(1, graph, originalDist);

  int maxRemovable = 0;

  for (int mask = 0; mask < (1 << k); ++mask) {
    vector<vector<pii>> tempGraph = graph;

    for (int i = 0; i < k; ++i) {
      if (mask & (1 << i)) {
        // Remove the fiber connection
        tempGraph[1].erase(remove_if(tempGraph[1].begin(), tempGraph[1].end(),
                                     [&](pii &edge) {
                                       return edge.first == fiberNodes[i];
                                     }),
                           tempGraph[1].end());
        tempGraph[fiberNodes[i]].erase(
            remove_if(tempGraph[fiberNodes[i]].begin(),
                      tempGraph[fiberNodes[i]].end(),
                      [&](pii &edge) { return edge.first == 1; }),
            tempGraph[fiberNodes[i]].end());
      }
    }

    vector<int> tempDist(n + 1, INF);
    dijkstra(1, tempGraph, tempDist);

    bool valid = true;
    for (int i = 2; i <= n; ++i) {
      if (tempDist[i] != originalDist[i]) {
        valid = false;
        break;
      }
    }

    if (valid) {
      maxRemovable = max(maxRemovable, __builtin_popcount(mask));
    }
  }

  cout << maxRemovable << endl;

  return 0;
}
```



### Explanation:

1. **Graph Representation**:
   - The graph is represented using an adjacency list where each node stores a list of pairs. Each pair contains a neighboring node and the latency of the connection.

2. **Dijkstra's Algorithm**:
   - We use Dijkstra's algorithm to compute the shortest paths from the HQ (node 1) to all other nodes. This gives us the original shortest path latencies.

