    regex_t regex;
    regmatch_t match;
    int reti;
    char error_buffer[100];

    // Компилируем регулярное выражение для поиска шестнадцатеричных констант
    if ((reti = regcomp(&regex, "(0x|0X)[0-9a-fA-F]+", REG_EXTENDED)) != 0) {
