假设我们有一个宽度为`width`、高度为`height`的图像，像素数据存储在一个名为`pixels`的数组中，每个像素使用3个字节表示RGB值。

```c
#include <stdio.h>
#include <stdlib.h>

#pragma pack(push, 1)
typedef struct {
    unsigned short bfType;
    unsigned int bfSize;
    unsigned short bfReserved1;
    unsigned short bfReserved2;
    unsigned int bfOffBits;
} BITMAPFILEHEADER;

typedef struct {
    unsigned int biSize;
    int biWidth;
    int biHeight;
    unsigned short biPlanes;
    unsigned short biBitCount;
    unsigned int biCompression;
    unsigned int biSizeImage;
    int biXPelsPerMeter;
    int biYPelsPerMeter;
    unsigned int biClrUsed;
    unsigned int biClrImportant;
} BITMAPINFOHEADER;
#pragma pack(pop)

void save_bmp(const char *filename, int width, int height, unsigned char *pixels) {
    BITMAPFILEHEADER fileHeader;
    BITMAPINFOHEADER infoHeader;
    FILE *file;
    int paddedWidth = (width * 3 + 3) & ~3; // 每行字节数必须是4的倍数
    int paddingSize = paddedWidth - width * 3;
    unsigned char *padding = (unsigned char *)malloc(paddingSize);
    if (!padding) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    for (int i = 0; i < paddingSize; i++) {
        padding[i] = 0; // 填充字节通常为0
    }

    file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        free(padding);
        return;
    }

    // 填充文件头
    fileHeader.bfType = 0x4D42; // 'BM'
    fileHeader.bfSize = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER) + paddedWidth * height;
    fileHeader.bfReserved1 = 0;
    fileHeader.bfReserved2 = 0;
    fileHeader.bfOffBits = sizeof(BITMAPFILEHEADER) + sizeof(BITMAPINFOHEADER);

    // 填充信息头
    infoHeader.biSize = sizeof(BITMAPINFOHEADER);
    infoHeader.biWidth = width;
    infoHeader.biHeight = height;
    infoHeader.biPlanes = 1;
    infoHeader.biBitCount = 24;
    infoHeader.biCompression = 0; // 无压缩
    infoHeader.biSizeImage = 0;
    infoHeader.biXPelsPerMeter = 0;
    infoHeader.biYPelsPerMeter = 0;
    infoHeader.biClrUsed = 0;
    infoHeader.biClrImportant = 0;

    // 写入文件头和信息头
    fwrite(&fileHeader, sizeof(BITMAPFILEHEADER), 1, file);
    fwrite(&infoHeader, sizeof(BITMAPINFOHEADER), 1, file);

    // 写入像素数据
    for (int y = height - 1; y >= 0; y--) { // BMP存储顺序是从下到上
        fwrite(&pixels[y * width * 3], width * 3, 1, file);
        fwrite(padding, paddingSize, 1, file);
    }

    fclose(file);
    free(padding);
}

int main() {
    int width = 100;
    int height = 100;
    unsigned char *pixels = (unsigned char *)malloc(width * height * 3);
    if (!pixels) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // 填充像素数据，这里简单地生成一个渐变图像
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int offset = (y * width + x) * 3;
            pixels[offset] = x * 255 / width;       // R
            pixels[offset + 1] = y * 255 / height; // G
            pixels[offset + 2] = 128;              // B
        }
    }

    save_bmp("output.bmp", width, height, pixels);

    free(pixels);
    return 0;
}
```

### 代码说明：
1. **结构体定义**：`BITMAPFILEHEADER`和`BITMAPINFOHEADER`分别对应BMP文件的文件头和信息头。
2. **内存对齐**：使用`#pragma pack(push, 1)`确保结构体成员按字节对齐，避免在写入文件时出现问题。
3. **填充字节**：BMP文件要求每行的字节数必须是4的倍数。如果像素数据的字节数不是4的倍数，需要添加填充字节。
4. **像素数据写入**：BMP文件的像素数据是从下到上存储的，因此需要倒序写入像素数据。
5. **主函数**：生成一个简单的渐变图像，并调用`save_bmp`函数将其保存为BMP文件。

### 注意事项：
- 确保内存中的像素数据格式正确（通常为24位RGB）。
- 处理大图像时，注意内存分配和文件操作的效率。
- 代码中的渐变图像生成部分仅为示例，实际应用中可能需要根据具体需求修改像素数据的生成方式。

运行上述代码后，将在当前目录下生成一个名为`output.bmp`的BMP文件。

