```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// 判断闰年
int is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 获取月份的天数
int get_days_in_month(int year, int month) {
    if (month == 2) {
        return is_leap_year(year) ? 29 : 28;
    } else if (month == 4 || month == 6 || month == 9 || month == 11) {
        return 30;
    } else {
        return 31;
    }
}

// 调整日期
void adjust_date(int *year, int *month, int *day) {
    int days = get_days_in_month(*year, *month);
    if (*day < 1) {
        *month -= 1;
        if (*month < 1) {
            *month = 12;
            *year -= 1;
        }
        *day = get_days_in_month(*year, *month);
    } else if (*day > days) {
        *day = 1;
        *month += 1;
        if (*month > 12) {
            *month = 1;
            *year += 1;
        }
    }
}

int main() {
    int year, month, day;
    int initial_year, initial_month, initial_day;

