        printf("7. 重置到初始日期\n");
        printf("8. 退出\n");
        printf("请选择操作: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                year += 1;
                adjust_date(&year, &month, &day);
                break;
            case 2:
                year -= 1;
                adjust_date(&year, &month, &day);
                break;
            case 3:
                month += 1;
                if (month > 12) {
                    month = 1;
                    year += 1;
                }
                adjust_date(&year, &month, &day);
                break;
            case 4:
                month -= 1;
                if (month < 1) {
                    month = 12;
                    year -= 1;
                }
                adjust_date(&year, &month, &day);
                break;
            case 5:
                day += 1;
                adjust_date(&year, &month, &day);
                break;
