// EEPROM 指令定义（以常见的 24xx 系列 EEPROM 为例）
#define EEPROM_WRITE  0x02
#define EEPROM_READ   0x03

// SSI 寄存器地址（根据具体硬件平台调整）
#define SSI_BASE_ADDR 0xXXXXXX00

// SSI 寄存器操作宏
#define SSI_TX_FIFO   (*(volatile uint32_t *)(SSI_BASE_ADDR + 0x00))
#define SSI_RX_FIFO   (*(volatile uint32_t *)(SSI_BASE_ADDR + 0x04))
#define SSI_SR        (*(volatile uint32_t *)(SSI_BASE_ADDR + 0x08))  // 状态寄存器
#define SSI_CR0       (*(volatile uint32_t *)(SSI_BASE_ADDR + 0x10))  // 控制寄存器 0
#define SSI_CR1       (*(volatile uint32_t *)(SSI_BASE_ADDR + 0x14))  // 控制寄存器 1

// 等待 SSI 就绪
static void ssi_wait_ready(void) {
    while (SSI_SR & (1 << 4)) {  // 等待 TX FIFO 非满
        ;
    }
}

// 发送一个字节
static void ssi_send_byte(uint8_t data) {
    ssi_wait_ready();
    SSI_TX_FIFO = data;
}

// 接收一个字节
static uint8_t ssi_recv_byte(void) {
    while (!(SSI_SR & (1 << 0))) {  // 等待 RX FIFO 非空
        ;
    }
    return (uint8_t)SSI_RX_FIFO;
}

// 初始化 SSI 接口
void ssi_init(void) {
    // 配置 SSI 控制寄存器（具体配置取决于硬件和时钟）
    SSI_CR0 = 0x0007;  // 8 位数据，SPI 模式
    SSI_CR1 = 0x0006;  // 使能 SSI，主模式
    // 其他配置...
}

// 向 EEPROM 写入一个字节
void eeprom_write_byte(uint16_t addr, uint8_t data) {
    ssi_init();  // 确保 SSI 初始化

    // 发送写指令
    ssi_send_byte(EEPROM_WRITE);
    ssi_send_byte((addr >> 8) & 0xFF);  // 高地址字节
    ssi_send_byte(addr & 0xFF);         // 低地址字节
    ssi_send_byte(data);

    // 等待写操作完成（根据 EEPROM 数据手册添加延迟）
    // ...
}

// 从 EEPROM 读取一个字节
