    uint8_t data;

    ssi_init();  // 确保 SSI 初始化

    // 发送读指令
    ssi_send_byte(EEPROM_READ);
    ssi_send_byte((addr >> 8) & 0xFF);  // 高地址字节
    ssi_send_byte(addr & 0xFF);         // 低地址字节

    // 读取数据
    data = ssi_recv_byte();

    return data;
}
