Poniżej przedstawiam przykład implementacji komunikacji klient-serwer w języku C, gdzie klient wysyła datagram z imieniem i nazwiskiem, a serwer odsyła ten tekst w dużych literach. Serwer działa w pętli nieskończonej, a port do komunikacji jest wybrany powyżej 4000.

### Serwer (server.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <ctype.h>

#define PORT 4001
#define BUFFER_SIZE 1024

int main() {
    int server_fd, n;
    struct sockaddr_in server_addr, client_addr;
    char buffer[BUFFER_SIZE];
    socklen_t addr_len = sizeof(client_addr);

    // Tworzenie gniazda UDP
    if ((server_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu serwera
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Wiązanie gniazda z adresem i portem
    if (bind(server_fd, (const struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Serwer nasłuchuje na porcie %d...\n", PORT);

    while (1) {
        // Odbieranie datagramu od klienta
        n = recvfrom(server_fd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &addr_len);
        buffer[n] = '\0';

        printf("Otrzymano: %s\n", buffer);

        // Zamiana tekstu na duże litery
        for (int i = 0; i < n; i++) {
            buffer[i] = toupper(buffer[i]);
        }

        // Wysyłanie odpowiedzi do klienta
        sendto(server_fd, buffer, n, 0, (const struct sockaddr *)&client_addr, addr_len);
    }

    close(server_fd);
    return 0;
}
```

