Poniżej znajduje się przykład implementacji komunikacji klient-serwer z użyciem gniazd domeny uniksowej (Unix Domain Sockets) w języku C. Klient wysyła tekst (imię i nazwisko), a serwer odbiera go, zamienia na wielkie litery i wysyła z powrotem do klienta.

### Serwer (`server.c`)

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/un.h>

#define SOCKET_PATH "/tmp/unix_socket"
#define BUFFER_SIZE 256

int main() {
    int server_fd, client_fd;
    struct sockaddr_un server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Tworzenie gniazda domeny uniksowej
    server_fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Konfiguracja adresu gniazda
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sun_family = AF_UNIX;
    strncpy(server_addr.sun_path, SOCKET_PATH, sizeof(server_addr.sun_path) - 1);

    // Usunięcie ewentualnie istniejącego gniazda
    unlink(SOCKET_PATH);

    // Wiązanie gniazda z adresem
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("bind");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Nasłuchiwanie połączeń
    if (listen(server_fd, 5) == -1) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Serwer nasłuchuje na gnieździe: %s\n", SOCKET_PATH);

    // Akceptowanie połączenia
    client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd == -1) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Odbieranie danych od klienta
    ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE, 0);
    if (bytes_received == -1) {
        perror("recv");
        close(client_fd);
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    buffer[bytes_received] = '\0';
    printf("Otrzymano od klienta: %s\n", buffer);

    // Zamiana tekstu na wielkie litery
    for (int i = 0; i < bytes_received; i++) {
        buffer[i] = toupper(buffer[i]);
    }

    // Wysyłanie odpowiedzi do klienta
    if (send(client_fd, buffer, bytes_received, 0) == -1) {
        perror("send");
    }

    // Zamykanie gniazd
    close(client_fd);
    close(server_fd);
    unlink(SOCKET_PATH);

    return 0;
}
```

