int isValidPointFormat(const char *str, double *x, double *y) {
    int len = strlen(str);
    if (len < 7 || str[0] != '(' || str[len - 1] != ')') {
        return 0;
    }

    char *comma = strchr(str + 1, ',');
    if (comma == NULL || comma - str > len - 3) {
        return 0;
    }

    *comma = '\0'; // Temporarily terminate the string at the comma
    char *endptr;
    *x = strtod(str + 1, &endptr);
    if (*endptr != '\0') {
        *comma = ','; // Restore the comma
        return 0;
    }

    *y = strtod(comma + 1, &endptr);
    if (*endptr != '\0' || endptr != str + len - 1) {
        return 0;
    }

    *comma = ','; // Restore the comma
    return 1;
}

// Function to calculate the area of a triangle given three points
double calculateTriangleArea(double x1, double y1, double x2, double y2, double x3, double y3) {
    return fabs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0);
