В данном примере мы будем считать, что "самый надежный путь" — это путь с максимальной минимальной надежностью ребер (т.е. путь, где минимальная надежность ребра максимальна).

```cpp
#include <iostream>
#include <limits>
#include <cstring>

using namespace std;

const int MAX_VERTICES = 100;
const int INF = numeric_limits<int>::min();

struct Edge {
    int to;
    int weight;
    Edge* next;
};

struct Graph {
    Edge* edges[MAX_VERTICES];
    int numVertices;
};

struct PriorityQueue {
    int items[MAX_VERTICES];
    int priorities[MAX_VERTICES];
    int size;

    PriorityQueue() : size(0) {}

    void push(int item, int priority) {
        items[size] = item;
        priorities[size] = priority;
        int i = size++;
        while (i > 0 && priorities[i] > priorities[(i - 1) / 2]) {
            swap(items[i], items[(i - 1) / 2]);
            swap(priorities[i], priorities[(i - 1) / 2]);
            i = (i - 1) / 2;
        }
    }

    int pop() {
        if (size == 0) return -1;
        int item = items[0];
        int priority = priorities[0];
        items[0] = items[--size];
        priorities[0] = priorities[size];
        int i = 0;
        while (true) {
            int largest = i;
            int left = 2 * i + 1;
            int right = 2 * i + 2;
            if (left < size && priorities[left] > priorities[largest]) {
                largest = left;
            }
            if (right < size && priorities[right] > priorities[largest]) {
                largest = right;
            }
            if (largest == i) break;
            swap(items[i], items[largest]);
            swap(priorities[i], priorities[largest]);
            i = largest;
        }
        return item;
    }

    bool empty() {
        return size == 0;
    }
};

void addEdge(Graph& graph, int from, int to, int weight) {
    Edge* edge = new Edge{to, weight, graph.edges[from]};
    graph.edges[from] = edge;
}

int maxReliabilityPath(Graph& graph, int start, int end) {
    int reliability[MAX_VERTICES];
    int predecessor[MAX_VERTICES];
    PriorityQueue pq;

    for (int i = 0; i < graph.numVertices; ++i) {
        reliability[i] = INF;
        predecessor[i] = -1;
    }

    reliability[start] = numeric_limits<int>::max();
    pq.push(start, reliability[start]);

    while (!pq.empty()) {
        int u = pq.pop();
        if (u == end) break;

        for (Edge* edge = graph.edges[u]; edge != nullptr; edge = edge->next) {
            int v = edge->to;
            int newReliability = min(reliability[u], edge->weight);
            if (newReliability > reliability[v]) {
                reliability[v] = newReliability;
                predecessor[v] = u;
                pq.push(v, reliability[v]);
            }
        }
    }

    if (reliability[end] == INF) {
        return INF;
    }

    return reliability[end];
}

int main() {
    Graph graph;
    graph.numVertices = 5;
    memset(graph.edges, 0, sizeof(graph.edges));

    addEdge(graph, 0, 1, 10);
    addEdge(graph, 0, 2, 5);
    addEdge(graph, 1, 3, 15);
    addEdge(graph, 2, 3, 4);
    addEdge(graph, 3, 4, 10);

    int start = 0;
    int end = 4;

    int result = maxReliabilityPath(graph, start, end);

    if (result == INF) {
        cout << "No path found" << endl;
    } else {
        cout << "Maximum reliability path reliability: " << result << endl;
    }

    return 0;
}
```

### Объяснение:
1. **Граф**: Представлен как массив списков смежности. Каждый элемент массива `edges` — это указатель на начало списка ребер, исходящих из вершины.
2. **Очередь с приоритетом**: Реализована как бинарная куча. Элементы добавляются и извлекаются в порядке убывания приоритета.
3. **Алгоритм**: Модификация алгоритма Дейкстры, где вместо поиска пути с минимальной суммой весов мы ищем путь с максимальной минимальной надежностью ребер.
4. **Результат**: Возвращает максимальную минимальную надежность пути от стартовой вершины до конечной.

Этот код не использует `<vector>` и `<queue>`, как того требовалось.

