```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERSECTIONS 31
#define INF -1  // Represents infinite routes

int main() {
    int city_id = 0;
    int num_streets;

    while (scanf("%d", &num_streets) == 1) {
        int graph[MAX_INTERSECTIONS][MAX_INTERSECTIONS];
        int largest_intersection = 0;

        // Initialize graph with 0 (no direct connection)
        for (int i = 0; i < MAX_INTERSECTIONS; i++) {
            for (int j = 0; j < MAX_INTERSECTIONS; j++) {
                graph[i][j] = (i == j) ? 0 : INF;
            }
        }

        // Read streets and update graph
        for (int i = 0; i < num_streets; i++) {
            int j, k;
            scanf("%d %d", &j, &k);
            largest_intersection = largest_intersection > j ? largest_intersection : j;
            largest_intersection = largest_intersection > k ? largest_intersection : k;
            graph[j][k] = 1;  // Direct route from j to k
        }

        largest_intersection++;  // Adjust for 0-based indexing

        // Floyd-Warshall algorithm to compute routes
        for (int k = 0; k < largest_intersection; k++) {
            for (int i = 0; i < largest_intersection; i++) {
                for (int j = 0; j < largest_intersection; j++) {
                    if (graph[i][k] != INF && graph[k][j] != INF) {
                        if (graph[i][j] == INF) {
                            graph[i][j] = graph[i][k] + graph[k][j];
                        } else {
                            graph[i][j] += graph[i][k] + graph[k][j];
                            // If there's a cycle, mark as infinite
                            if (graph[i][j] > 1 && graph[k][k] != INF) {
                                graph[i][j] = INF;
                            }
                        }
                    }
                }
            }
        }

        // Detect cycles to mark infinite routes
        for (int i = 0; i < largest_intersection; i++) {
            if (graph[i][i] != 0) {
                graph[i][i] = INF;
                for (int j = 0; j < largest_intersection; j++) {
                    if (graph[i][j] != INF || graph[j][i] != INF) {
                        graph[i][j] = graph[j][i] = INF;
                    }
                }
            }
        }

        // Print the matrix for the current city
        printf("matrix for city %d\n", city_id++);
        for (int i = 0; i < largest_intersection; i++) {
            for (int j = 0; j < largest_intersection; j++) {
                if (j > 0) printf(" ");
                if (graph[i][j] == INF) {
                    printf("-1");
                } else {
                    printf("%d", graph[i][j]);
                }
            }
