#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>

#define DEVICE_FILE "/dev/mmap_comm"
#define MEM_SIZE 4096

int main() {
    int fd;
    char *mapped_buffer;

    // 打开设备文件
    fd = open(DEVICE_FILE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device file");
        return EXIT_FAILURE;
    }

    // 映射内核缓冲区到用户空间
    mapped_buffer = (char *)mmap(NULL, MEM_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_buffer == MAP_FAILED) {
        perror("Failed to mmap");
        close(fd);
        return EXIT_FAILURE;
    }

    // 写入数据到共享内存
    strcpy(mapped_buffer, "Hello from user space!");

    // 读取并打印内核缓冲区中的数据
    printf("Kernel buffer: %s\n", mapped_buffer);

    // 解除映射
    if (munmap(mapped_buffer, MEM_SIZE) < 0) {
        perror("Failed to munmap");
    }

    // 关闭设备文件
    close(fd);

    return EXIT_SUCCESS;
}
```

