                processes[count].ppid = ppid;
                processes[count].is_defunct = is_process_defunct(pid);
                count++;
            }
        }
    }
    closedir(dir);
    return count;
}

// Function to check if a process is in the tree rooted at root_pid
bool is_in_tree(Process processes[], int count, pid_t root_pid, pid_t target_pid) {
    for (int i = 0; i < count; i++) {
        if (processes[i].pid == target_pid) {
            if (processes[i].ppid == root_pid) return true;
            return is_in_tree(processes, count, root_pid, processes[i].ppid);
        }
    }
    return false;
}

