    for (int a = 0; a <= sqrt(n); a++) {
        int b_squared = n - a * a;
        if (b_squared >= 0 && isPerfectSquare(b_squared)) {
            return 1; // Tìm thấy cặp (a, b) thỏa mãn
        }
    }
    return 0; // Không tìm thấy cặp nào
}

