    printf("Nhập một số nguyên n: ");
    scanf("%d", &n);

    if (isSumOfTwoSquares(n)) {
        printf("%d là tổng của hai số chính phương.\n", n);
    } else {
        printf("%d không phải là tổng của hai số chính phương.\n", n);
