```c
#include <stdio.h>
#include <time.h>

// 判断闰年
int is_leap_year(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

// 获取月份的天数
int get_month_days(int year, int month) {
    int days[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (month == 2 && is_leap_year(year)) {
        return 29;
    }
    return days[month - 1];
}

// 打印当前日期
void print_date(int year, int month, int day) {
    printf("%04d-%02d-%02d\n", year, month, day);
}

int main() {
    int year, month, day;
    int initial_year, initial_month, initial_day;
    int choice;

    // 输入初始日期
    printf("请输入初始日期 (YYYY MM DD): ");
    scanf("%d %d %d", &year, &month, &day);

    // 保存初始日期
    initial_year = year;
    initial_month = month;
    initial_day = day;

    while (1) {
        print_date(year, month, day);
        printf("\n请选择操作:\n");
        printf("1. 增加年份\n");
        printf("2. 减少年份\n");
        printf("3. 增加月份\n");
        printf("4. 减少月份\n");
        printf("5. 增加日期\n");
        printf("6. 减少日期\n");
        printf("7. 重置为初始日期\n");
        printf("8. 退出\n");
        printf("输入选择: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                year++;
                break;
            case 2:
                year--;
                break;
            case 3:
                month++;
                if (month > 12) {
                    month = 1;
                    year++;
                }
                break;
            case 4:
                month--;
                if (month < 1) {
                    month = 12;
                    year--;
                }
                break;
            case 5:
                day++;
                if (day > get_month_days(year, month)) {
                    day = 1;
                    month++;
                    if (month > 12) {
                        month = 1;
                        year++;
                    }
                }
                break;
            case 6:
                day--;
                if (day < 1) {
                    month--;
                    if (month < 1) {
                        month = 12;
                        year--;
                    }
                    day = get_month_days(year, month);
                }
                break;
            case 7:
                year = initial_year;
                month = initial_month;
                day = initial_day;
                printf("日期已重置为初始日期。\n");
                break;
            case 8:
                return 0;
            default:
                printf("无效的选择，请重新输入。\n");
        }
    }

    return 0;
}
