#include <libwebsockets.h>
#include <uv.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SERVER_ADDRESS "ws://echo.websocket.org"
#define PORT 80

static uv_loop_t *loop;
static struct lws_context *context;
static struct lws *wsi;

static int callback_websocket(struct lws *wsi, enum lws_callback_reasons reason, void *user, void *in, size_t len) {
    switch (reason) {
        case LWS_CALLBACK_CLIENT_ESTABLISHED:
            printf("WebSocket connection established\n");
            lws_callback_on_writable(wsi);
            break;

        case LWS_CALLBACK_CLIENT_RECEIVE:
            printf("Received: %s\n", (char *)in);
            break;

        case LWS_CALLBACK_CLIENT_WRITEABLE: {
            const char *message = "Hello, WebSocket Server!";
            lws_write(wsi, message, strlen(message), LWS_WRITE_TEXT);
            printf("Sent: %s\n", message);
            break;
        }

        case LWS_CALLBACK_CLOSED:
            printf("WebSocket connection closed\n");
            uv_stop(loop);
            break;

        default:
            break;
    }

    return 0;
}

static struct lws_protocols protocols[] = {
    {
        "ws",
        callback_websocket,
        0,
        0,
    },
    { NULL, NULL, 0, 0 } /* terminator */
};

static void connect_to_server(uv_timer_t *handle) {
    struct lws_client_connect_info ccinfo = {0};
    ccinfo.context = context;
    ccinfo.address = SERVER_ADDRESS;
    ccinfo.port = PORT;
    ccinfo.path = "/";
    ccinfo.host = lws_canonical_hostname(context);
    ccinfo.origin = "origin";
    ccinfo.ietf_version_or_minus_one = -1;
    ccinfo.protocol = protocols[0].name;
    ccinfo.pwsi = &wsi;

    if (!lws_client_connect_via_info(&ccinfo)) {
        printf("Failed to connect to WebSocket server\n");
        uv_stop(loop);
    }
}

int main() {
    loop = uv_default_loop();

    struct lws_context_creation_info info;
    memset(&info, 0, sizeof(info));
    info.port = CONTEXT_PORT_NO_LISTEN;
    info.protocols = protocols;
    info.gid = -1;
    info.uid = -1;

    context = lws_create_context(&info);
    if (!context) {
        printf("Failed to create libwebsockets context\n");
        return -1;
    }

    uv_timer_t connect_timer;
    uv_timer_init(loop, &connect_timer);
    uv_timer_start(&connect_timer, connect_to_server, 0, 0);

    uv_run(loop, UV_RUN_DEFAULT);

    lws_context_destroy(context);
    return 0;
}
