        }

        // Перемещаем указатели
        prev = curr;
        curr = next_node;
        if (curr != NULL) {
            next = curr->next;
        }

        // Обновляем последний и предпоследний узлы
        if (second_last != NULL) {
            last = second_last;
            second_last = second_last->next;
        }
    }
