```c
#include <stdio.h>
#include <string.h>

int manacher(char *s, int n) {
    char *t = (char *)malloc((n * 2 + 1) * sizeof(char));
    t[0] = '#';
    for (int i = 0; i < n; i++) {
        t[2 * i + 1] = s[i];
        t[2 * i + 2] = '#';
    }
    t[2 * n + 1] = '\0';

    int *p = (int *)malloc((2 * n + 1) * sizeof(int));
    int c = 0, r = 0;
    for (int i = 1; i <= 2 * n; i++) {
        int mirror = 2 * c - i;
        if (i < r)
            p[i] = (p[mirror] < r - i) ? p[mirror] : r - i;
        while (t[i + p[i] + 1] == t[i - p[i] - 1] && i + p[i] + 1 < 2 * n + 1)
            p[i]++;
        if (i + p[i] > r) {
            c = i;
            r = i + p[i];
        }
    }

    int max_len = 0;
    for (int i = 1; i <= 2 * n; i++) {
        if (p[i] > max_len)
            max_len = p[i];
    }

    free(t);
    free(p);
    return max_len;
}

int main() {
