#### **1. 公共工具类（文件传输与序列化）**
```java
import java.io.*;

public class TransferUtil {
    // 发送文件
    public static void sendFile(OutputStream os, File file) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(os)) {
            oos.writeObject(file.getName());
            try (FileInputStream fis = new FileInputStream(file)) {
                byte[] buffer = new byte[4096];
                int len;
                while ((len = fis.read(buffer)) != -1) {
                    oos.write(buffer, 0, len);
                }
            }
        }
    }

    // 接收文件
    public static void receiveFile(InputStream is, String savePath) throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(is)) {
            String fileName = (String) ois.readObject();
            try (FileOutputStream fos = new FileOutputStream(savePath + File.separator + fileName)) {
                byte[] buffer = new byte[4096];
                int len;
                while ((len = ois.read(buffer)) != -1) {
                    fos.write(buffer, 0, len);
                }
            }
        } catch (ClassNotFoundException e) {
            throw new IOException("文件接收失败", e);
        }
    }
}
```

