import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.io.*;
import java.net.Socket;
import java.util.concurrent.TimeUnit;

public class ClientFrame extends JFrame {
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendBtn, fileBtn;
    private Socket socket;
    private ObjectOutputStream oos;
    private ObjectInputStream ois;

    public ClientFrame() {
        initializeUI();
        connectToServer();
    }

    private void initializeUI() {
        setTitle("用户端");
        setSize(400, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        JPanel bottomPanel = new JPanel();
        inputField = new JTextField(20);
        sendBtn = new JButton("发送");
        fileBtn = new JButton("发送图片");

        sendBtn.addActionListener(this::sendMessage);
        fileBtn.addActionListener(this::sendFile);

        bottomPanel.add(inputField);
        bottomPanel.add(sendBtn);
        bottomPanel.add(fileBtn);
        add(bottomPanel, BorderLayout.SOUTH);
    }

    private void connectToServer() {
        try {
            socket = new Socket("localhost", 8888);
            oos = new ObjectOutputStream(socket.getOutputStream());
            ois = new ObjectInputStream(socket.getInputStream());

            // 接收消息线程
            new Thread(() -> {
                try {
                    while (true) {
                        Object obj = ois.readObject();
                        if (obj instanceof String) {
                            chatArea.append("客服: " + obj + "\n");
                        } else if (obj instanceof File) {
                            File file = (File) obj;
                            TransferUtil.receiveFile(ois, "received_files");
                            chatArea.append("客服: 文件 " + file.getName() + " 已接收\n");
                        }
                    }
                } catch (IOException | ClassNotFoundException e) {
                    JOptionPane.showMessageDialog(this, "客服已断开连接");
                }
            }).start();

            // 超时检测线程
            new Thread(() -> {
                try {
