```java
import javax.swing.*;
import java.awt.*;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServerFrame extends JFrame {
    private JTextArea activeUsersArea;
    private Map<String, ClientHandler> clients = new HashMap<>();
    private ExecutorService pool = Executors.newCachedThreadPool();

    public ServerFrame() {
        initializeUI();
        startServer();
    }

    private void initializeUI() {
        setTitle("客服端");
        setSize(400, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        activeUsersArea = new JTextArea();
        activeUsersArea.setEditable(false);
        add(new JScrollPane(activeUsersArea), BorderLayout.CENTER);
    }

    private void startServer() {
        try (ServerSocket server = new ServerSocket(8888)) {
            while (true) {
                Socket clientSocket = server.accept();
                pool.submit(() -> handleNewClient(clientSocket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void handleNewClient(Socket socket) {
        try {
            ObjectInputStream ois = new ObjectInputStream(socket.getInputStream());
            ObjectOutputStream oos = new ObjectOutputStream(socket.getOutputStream());

            String clientId = socket.getInetAddress().getHostAddress() + ":" + socket.getPort();
            ClientHandler handler = new ClientHandler(clientId, ois, oos);
            clients.put(clientId, handler);

            SwingUtilities.invokeLater(() -> {
                activeUsersArea.append("新用户: " + clientId + "\n");
                JOptionPane.showMessageDialog(this, "新用户请求服务: " + clientId);
                int choice = JOptionPane.showConfirmDialog(this, "是否接受服务？");
                if (choice == JOptionPane.YES_OPTION) {
                    handler.startChat();
                } else {
                    oos.writeObject("客服当前繁忙，请稍后再试");
                    oos.close();
                    socket.close();
                    clients.remove(clientId);
                }
            });

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private class ClientHandler {
        private String clientId;
        private ObjectInputStream ois;
        private ObjectOutputStream oos;
        private JFrame chatFrame;
        private JTextArea chatArea;
        private File logFile;

        public ClientHandler(String clientId, ObjectInputStream ois, ObjectOutputStream oos) {
            this.clientId = clientId;
            this.ois = ois;
            this.oos = oos;
            this.logFile = new File("chat_logs/" + clientId + ".log");
            loadChatHistory();
        }

        private void loadChatHistory() {
            if (logFile.exists()) {
                try (BufferedReader reader = new BufferedReader(new FileReader(logFile))) {
                    String line;
                    StringBuilder history = new StringBuilder();
                    while ((line = reader.readLine()) != null) {
                        history.append(line).append("\n");
                    }
                    chatArea.setText(history.toString());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void saveChatHistory(String message) {
            try (BufferedWriter writer = new BufferedWriter(new FileWriter(logFile, true))) {
                writer.write(message);
                writer.newLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void startChat() {
            chatFrame = new JFrame("与 " + clientId + " 的聊天");
            chatFrame.setSize(400, 600);
            chatFrame.setLayout(new BorderLayout());

            chatArea = new JTextArea();
            chatArea.setEditable(false);
            chatFrame.add(new JScrollPane(chatArea), BorderLayout.CENTER);

            JTextField inputField = new JTextField();
            JButton sendBtn = new JButton("发送");
            JButton fileBtn = new JButton("发送文件");

            sendBtn.addActionListener(e -> sendMessage(inputField.getText()));
            fileBtn.addActionListener(e -> sendFile());

            JPanel bottomPanel = new JPanel();
            bottomPanel.add(inputField);
            bottomPanel.add(sendBtn);
            bottomPanel.add(fileBtn);
            chatFrame.add(bottomPanel, BorderLayout.SOUTH);

            chatFrame.setVisible(true);

            // 接收消息线程
            new Thread(() -> {
                try {
                    while (true) {
                        Object obj = ois.readObject();
                        if (obj instanceof String) {
                            String msg = "用户: " + obj;
                            chatArea.append(msg + "\n");
                            saveChatHistory(msg);
                        } else if (obj instanceof File) {
                            File file = (File) obj;
                            TransferUtil.receiveFile(ois, "received_files");
                            String msg = "用户: 文件 " + file.getName() + " 已接收";
                            chatArea.append(msg + "\n");
                            saveChatHistory(msg);
                        }
                    }
                } catch (IOException | ClassNotFoundException ex) {
                    chatFrame.dispose();
                    clients.remove(clientId);
                }
            }).start();
        }

        private void sendMessage(String msg) {
            if (!msg.isEmpty()) {
                try {
                    oos.writeObject("客服: " + msg);
                    oos.flush();
                    chatArea.append("我: " + msg + "\n");
                    saveChatHistory("我: " + msg);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void sendFile() {
            JFileChooser chooser = new JFileChooser();
            if (chooser.showOpenDialog(chatFrame) == JFileChooser.APPROVE_OPTION) {
                File file = chooser.getSelectedFile();
                try {
                    oos.writeObject(file);
                    TransferUtil.sendFile(oos, file);
                    chatArea.append("我: 发送了文件 " + file.getName() + "\n");
                    saveChatHistory("我: 发送了文件 " + file.getName());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(ServerFrame::new);
    }
}
```

