### 2. 创建控制器
创建一个控制器来处理文件下载请求。我们将实现两个方法：一个用于下载任意文件，另一个用于下载TXT文件作为图片（假设TXT文件内容是图片的Base64编码）。

```java
import org.springframework.core.io.FileSystemResource;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Base64;

@RestController
@RequestMapping("/download")
public class DownloadController {

    private static final String FILE_PATH = "path/to/your/files/";

    @GetMapping("/file/{fileName}")
    public ResponseEntity<Resource> downloadFile(@PathVariable String fileName) {
        File file = new File(FILE_PATH + fileName);
        if (!file.exists()) {
            return ResponseEntity.notFound().build();
        }

        Resource resource = new FileSystemResource(file);
        HttpHeaders headers = new HttpHeaders();
        headers.add(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=" + fileName);
        headers.add(HttpHeaders.CONTENT_TYPE, MediaType.APPLICATION_OCTET_STREAM_VALUE);

        return ResponseEntity.ok()
                .headers(headers)
                .body(resource);
    }

    @GetMapping("/txt-as-image/{txtFileName}")
    public ResponseEntity<byte[]> downloadTxtAsImage(@PathVariable String txtFileName) {
        try {
            Path path = Paths.get(FILE_PATH + txtFileName);
            String content = new String(Files.readAllBytes(path));
            byte[] imageBytes = Base64.getDecoder().decode(content);

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.IMAGE_PNG); // 假设解码后的图片是PNG格式
            headers.setContentLength(imageBytes.length);
            headers.setContentDispositionFormData("attachment", txtFileName.replace(".txt", ".png"));

            return ResponseEntity.ok()
                    .headers(headers)
                    .body(imageBytes);
        } catch (Exception e) {
            return ResponseEntity.status(500).body(null);
        }
    }
}
```

### 3. 配置文件路径
在`application.properties`或`application.yml`中配置文件存储路径（可选）：

