class UserClient {
    private Socket socket;
    private PrintWriter out;
    private BufferedReader in;
    private JFrame frame;
    private JTextArea chatArea;
    private JTextField inputField;
    private String serverAddress;
    private int serverPort;

    public UserClient(String address, int port) {
        serverAddress = address;
        serverPort = port;
        initializeUI();
    }

    private void initializeUI() {
        frame = new JFrame("用户端");
        frame.setSize(400, 600);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(chatArea);

        inputField = new JTextField();
        inputField.addActionListener(e -> sendMessage());

        JButton connectButton = new JButton("连接客服");
        connectButton.addActionListener(e -> connectToServer());

        JButton sendImageButton = new JButton("发送图片");
        sendImageButton.addActionListener(e -> sendImage());

        JPanel panel = new JPanel();
        panel.add(inputField);
        panel.add(sendImageButton);
        panel.add(connectButton);

        frame.add(scrollPane, BorderLayout.CENTER);
        frame.add(panel, BorderLayout.SOUTH);
        frame.setVisible(true);
    }

    private void connectToServer() {
        new Thread(() -> {
            try {
                socket = new Socket(serverAddress, serverPort);
                out = new PrintWriter(socket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

                // 等待客服响应
                new Thread(this::listenForResponse).start();
                out.println("CONNECT_REQUEST");

                // 超时处理
                Timer timer = new Timer();
                timer.schedule(new TimerTask() {
                    @Override
                    public void run() {
                        chatArea.append("客服忙，请稍后再试...\n");
                        disconnect();
                    }
                }, 10000); // 10秒超时

            } catch (IOException e) {
                chatArea.append("连接失败: " + e.getMessage() + "\n");
            }
        }).start();
    }

    private void listenForResponse() {
        try {
            String response;
            while ((response = in.readLine()) != null) {
                if (response.startsWith("FILE:")) {
                    receiveFile(response.substring(5));
                } else {
                    chatArea.append("客服: " + response + "\n");
                }
            }
        } catch (IOException e) {
            chatArea.append("连接断开\n");
        }
    }

    private void sendMessage() {
        String message = inputField.getText().trim();
        if (!message.isEmpty()) {
            out.println(message);
            chatArea.append("我: " + message + "\n");
            inputField.setText("");
        }
    }

    private void sendImage() {
        JFileChooser chooser = new JFileChooser();
        if (chooser.showOpenDialog(frame) == JFileChooser.APPROVE_OPTION) {
            File file = chooser.getSelectedFile();
            try {
                out.println("FILE:" + file.getName());
                FileInputStream fis = new FileInputStream(file);
                OutputStream os = socket.getOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    os.write(buffer, 0, bytesRead);
                }
                os.flush();
                chatArea.append("我: [图片] " + file.getName() + "\n");
            } catch (IOException e) {
                chatArea.append("发送失败: " + e.getMessage() + "\n");
            }
        }
    }

    private void receiveFile(String fileName) {
        try {
            FileOutputStream fos = new FileOutputStream("received_" + fileName);
            InputStream is = socket.getInputStream();
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
            fos.close();
            chatArea.append("客服: [文件] " + fileName + "\n");
        } catch (IOException e) {
            chatArea.append("接收失败: " + e.getMessage() + "\n");
        }
    }

    private void disconnect() {
        try {
            if (socket != null) socket.close();
        } catch (IOException e) {}
    }

    public static void main(String[] args) {
        new UserClient("localhost", 12345);
    }
