// 客服端
class CustomerServiceServer {
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clients = new ConcurrentHashMap<>();
    private JFrame frame;
    private JTextArea clientListArea;
    private JTextArea chatArea;
    private String currentClient;

    public CustomerServiceServer(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        initializeUI();
        listenForClients();
    }

    private void initializeUI() {
        frame = new JFrame("客服端");
        frame.setSize(600, 800);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        clientListArea = new JTextArea(10, 30);
        clientListArea.setEditable(false);
        JScrollPane clientScroll = new JScrollPane(clientListArea);

        chatArea = new JTextArea(20, 30);
        chatArea.setEditable(false);
        JScrollPane chatScroll = new JScrollPane(chatArea);

        JButton acceptButton = new JButton("接受服务");
        acceptButton.addActionListener(e -> acceptClient());

        JButton rejectButton = new JButton("拒绝服务");
        rejectButton.addActionListener(e -> rejectClient());

        JButton sendFileButton = new JButton("发送文件");
        sendFileButton.addActionListener(e -> sendFile());

        JPanel buttonPanel = new JPanel();
        buttonPanel.add(acceptButton);
        buttonPanel.add(rejectButton);
        buttonPanel.add(sendFileButton);

        frame.add(clientScroll, BorderLayout.NORTH);
        frame.add(chatScroll, BorderLayout.CENTER);
        frame.add(buttonPanel, BorderLayout.SOUTH);
        frame.setVisible(true);
    }

    private void listenForClients() {
        new Thread(() -> {
            while (true) {
                try {
                    Socket clientSocket = serverSocket.accept();
                    String clientId = clientSocket.getInetAddress().getHostAddress() + ":" + 
                                      clientSocket.getPort();
                    ClientHandler handler = new ClientHandler(clientSocket, clientId);
                    clients.put(clientId, handler);
                    updateClientList();
                    chatArea.append("新用户连接: " + clientId + "\n");
                } catch (IOException e) {
                    System.err.println("接受连接失败: " + e.getMessage());
                }
            }
        }).start();
    }

    private void updateClientList() {
        StringBuilder sb = new StringBuilder();
        for (String client : clients.keySet()) {
            sb.append(client).append("\n");
        }
        clientListArea.setText(sb.toString());
    }

    private void acceptClient() {
        String selected = clientListArea.getSelectedText();
        if (selected != null && clients.containsKey(selected.trim())) {
            currentClient = selected.trim();
            ClientHandler handler = clients.get(currentClient);
            loadChatHistory(currentClient);
            handler.sendMessage("客服已接入，请开始咨询");
        }
    }

    private void rejectClient() {
        if (currentClient != null) {
            clients.get(currentClient).sendMessage("客服当前繁忙，请稍后再试");
            clients.get(currentClient).disconnect();
            clients.remove(currentClient);
            updateClientList();
            currentClient = null;
        }
    }

    private void sendFile() {
        if (currentClient != null) {
            JFileChooser chooser = new JFileChooser();
            if (chooser.showOpenDialog(frame) == JFileChooser.APPROVE_OPTION) {
                File file = chooser.getSelectedFile();
                clients.get(currentClient).sendFile(file);
                chatArea.append("我: [文件] " + file.getName() + "\n");
                saveChatHistory(currentClient, "我: [文件] " + file.getName());
            }
        }
    }

    private void loadChatHistory(String clientId) {
        File file = new File("chat_history_" + clientId + ".txt");
        if (file.exists()) {
            try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                String line;
                chatArea.setText("");
                while ((line = br.readLine()) != null) {
                    chatArea.append(line + "\n");
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void saveChatHistory(String clientId, String message) {
        try (PrintWriter pw = new PrintWriter(new FileWriter(
            "chat_history_" + clientId + ".txt", true))) {
            pw.println(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class ClientHandler {
        private Socket socket;
        private String clientId;
        private PrintWriter out;
        private BufferedReader in;

        public ClientHandler(Socket socket, String clientId) {
            this.socket = socket;
            this.clientId = clientId;
            try {
                out = new PrintWriter(socket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                new Thread(this::listenForMessages).start();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void listenForMessages() {
            try {
                String message;
                while ((message = in.readLine()) != null) {
                    if (message.startsWith("FILE:")) {
                        receiveFile(message.substring(5));
                    } else {
                        chatArea.append(clientId + ": " + message + "\n");
                        saveChatHistory(clientId, clientId + ": " + message);
                    }
                }
            } catch (IOException e) {
                disconnect();
            }
        }

        public void sendMessage(String message) {
            out.println(message);
        }

        public void sendFile(File file) {
            try {
                out.println("FILE:" + file.getName());
                FileInputStream fis = new FileInputStream(file);
                OutputStream os = socket.getOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    os.write(buffer, 0, bytesRead);
                }
                os.flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void receiveFile(String fileName) {
            try {
                FileOutputStream fos = new FileOutputStream("received_" + fileName);
                InputStream is = socket.getInputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    fos.write(buffer, 0, bytesRead);
                }
                fos.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void disconnect() {
            try {
                socket.close();
            } catch (IOException e) {}
            clients.remove(clientId);
            updateClientList();
        }
    }

    public static void main(String[] args) throws IOException {
        new CustomerServiceServer(12345);
    }
}
