```kotlin
data class Point(val x: Double, val y: Double)

fun fittingTrailsMultiple(points: List<Point>? = null, number: Int, trailPoints: List<Point> = emptyList()): List<Point> {
    val newPoints = points ?: trailPoints
    var result = newPoints
    for (i in 0 until number) {
        result = fittingTrails(result)
    }
    return result
}

fun fittingTrails(points: List<Point>): List<Point> {
    val newPoints = mutableListOf<Point>()
    for (i in points.indices) {
        if (i > 2 && i < points.size - 3) {
            newPoints.add(pointsAvg(points, i))
        } else {
            newPoints.add(points[i])
        }
    }
    return newPoints
}

fun pointsAvg(points: List<Point>, i: Int): Point {
    val x = (points[i - 2].x + points[i - 1].x + points[i].x + points[i + 1].x + points[i + 2].x) / 5
    val y = (points[i - 2].y + points[i - 1].y + points[i].y + points[i + 1].y + points[i + 2].y) / 5
    return Point(x, y)
}
