public class Server {
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clients = new HashMap<>();
    private ServerGUI gui;

    public Server(int port) {
        try {
            serverSocket = new ServerSocket(port);
            gui = new ServerGUI(this);
            new Thread(this::acceptClients).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void acceptClients() {
        while (true) {
            try {
                Socket socket = serverSocket.accept();
                ClientHandler handler = new ClientHandler(socket, this);
                clients.put(socket.getInetAddress().getHostAddress(), handler);
                gui.appendMessage("新用户连接: " + socket.getInetAddress().getHostAddress());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public void removeClient(String ip) {
        clients.remove(ip);
        gui.appendMessage("用户断开连接: " + ip);
    }

    public void sendMessageToClient(String ip, String message) {
        ClientHandler handler = clients.get(ip);
        if (handler != null) {
            handler.sendMessage(message);
        }
    }

