import java.util.Random;

public class RandomWordSelector {

    public static void main(String[] args) {
        String fileName = "input.txt"; // Replace with your file name
        List<String> words = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] lineWords = line.split("\\s+"); // Split by one or more whitespace characters
                for (String word : lineWords) {
                    if (!word.isEmpty()) {
                        words.add(word);
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Error reading the file: " + e.getMessage());
            return;
        }

        int totalWords = words.size();
        if (totalWords < 10) {
            System.out.println("The file does not contain enough words to select 10 randomly.");
            return;
        }

        List<String> selectedWords = selectRandomWords(words, 10);
        System.out.println("Randomly selected words:");
        for (String word : selectedWords) {
            System.out.println(word);
        }
    }

    private static List<String> selectRandomWords(List<String> words, int count) {
        List<String> selectedWords = new ArrayList<>();
        Random random = new Random();
        int totalWords = words.size();

        for (int i = 0; i < count; i++) {
            int randomIndex = random.nextInt(totalWords);
            selectedWords.add(words.get(randomIndex));
        }

        return selectedWords;
    }
}
