public class TCPPacketServer {
    private static int port = 1024;
    private static ExecutorService pool = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        try {
            ServerSocket serverSocket = new ServerSocket(port);
            System.out.println("Server started on port " + port);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                pool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static class ClientHandler implements Runnable {
        private Socket clientSocket;

        public ClientHandler(Socket socket) {
            this.clientSocket = socket;
        }

        public void run() {
            try (ObjectOutputStream oos = new ObjectOutputStream(clientSocket.getOutputStream());
                 ObjectInputStream ois = new ObjectInputStream(clientSocket.getInputStream())) {

                Packet packet;
                while ((packet = (Packet) ois.readObject()) != null && !packet.getData().equalsIgnoreCase("CLOSE")) {
                    System.out.println("FROM CLIENT " + clientSocket.getRemoteSocketAddress() + ": Packet SerialNo#" + packet.getSerialNo() + " with data: " + packet.getData());

                    // Convert data to uppercase and send back as acknowledgment
                    String ackData = packet.getData().toUpperCase();
                    Packet responsePacket = new Packet(packet.getSerialNo(), ackData);
                    oos.writeObject(responsePacket);
                    oos.flush();
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            } finally {
                try {
                    clientSocket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
