import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Generator {

    /**
     * 生成MD5值
     *
     * @param wmPoiId  long类型的wmPoiId
     * @param noticeId long类型的noticeId
     * @param str      字符串
     * @return MD5值
     */
    public static String generateMD5(long wmPoiId, long noticeId, String str) {
        try {
            // 将wmPoiId和noticeId拼接成字符串
            String combinedId = wmPoiId + "" + noticeId;

            // 将combinedId和字符串拼接在一起
            String input = combinedId + str;

            // 创建MessageDigest实例
            MessageDigest md = MessageDigest.getInstance("MD5");

            // 更新输入
            md.update(input.getBytes());

            // 获取字节数组
            byte[] digest = md.digest();

            // 将字节数组转换为十六进制字符串
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }

            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }

