import org.bytedeco.javacpp.BytePointer;
import org.bytedeco.javacv.*;
import org.bytedeco.opencv.opencv_core.IplImage;

import javax.swing.*;
import java.io.IOException;
import java.io.InputStream;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class H264StreamReceiver {

    private static final int PORT = 12345;
    private static final int FRAME_RATE = 30;

    public static void main(String[] args) throws IOException {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Waiting for connection on port " + PORT);
            Socket socket = serverSocket.accept();
            System.out.println("Connection established");

            ExecutorService executor = Executors.newSingleThreadExecutor();
            executor.submit(() -> processStream(socket));
        }
    }

    private static void processStream(Socket socket) {
        try (InputStream inputStream = socket.getInputStream()) {
            FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(inputStream);
            grabber.setFormat("h264");
            grabber.start();

            CanvasFrame canvas = new CanvasFrame("H.264 Stream", CanvasFrame.getDefaultGamma() / grabber.getGamma());
            canvas.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            canvas.setAlwaysOnTop(true);

            long startTime = System.nanoTime();
            long frameCount = 0;

            while (true) {
                Frame frame = grabber.grab();
                if (frame == null) {
                    break;
                }

                if (frame.image instanceof IplImage) {
                    IplImage img = (IplImage) frame.image;
                    canvas.showImage(img);
                }

                frameCount++;
                long elapsedTime = (System.nanoTime() - startTime) / 1_000_000;
                if (elapsedTime > 1000) {
                    System.out.println("Frame rate: " + frameCount + " fps");
                    frameCount = 0;
                    startTime = System.nanoTime();
                }
            }

            grabber.stop();
            canvas.dispose();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
```

### 3. 代码说明

- **Socket连接**：使用`ServerSocket`监听指定端口，等待客户端连接。
