            }
        }
    }

    public void removeClient(ClientHandler clientHandler) {
        clients.remove(clientHandler);
        serverGUI.updateClientList(clients);
    }

    public static void main(String[] args) throws IOException {
        new Server(12345);
    }
}

class ClientHandler implements Runnable {
    private Socket socket;
    private Server server;
    private ObjectInputStream in;
    private ObjectOutputStream out;
    private String clientId;
    private ChatHistory chatHistory;

    public ClientHandler(Socket socket, Server server) throws IOException {
        this.socket = socket;
        this.server = server;
        out = new ObjectOutputStream(socket.getOutputStream());
        in = new ObjectInputStream(socket.getInputStream());
        clientId = socket.getInetAddress().getHostAddress();
        chatHistory = new ChatHistory(clientId);
    }

    @Override
    public void run() {
        try {
            while (true) {
                Object obj = in.readObject();
                if (obj instanceof String) {
                    String message = (String) obj;
                    chatHistory.saveMessage("User: " + message);
                    server.getServerGUI().updateChatHistory(clientId, "User: " + message);
                } else if (obj instanceof File) {
