使用 Java 和 Jsoup 抓取网站内容是一个常见的任务。下面是一个示例代码，用于抓取 `https://www.tyjrchina.org.cn/newsInfor/news` 网站的新闻动态模块内容，包括标题、发布时间、具体文章内容，并处理文章内容中的相对图片地址，将其转换为绝对地址。

```java
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class NewsCrawler {

    private static final String URL = "https://www.tyjrchina.org.cn/newsInfor/news";
    private static final String BASE_URL = "https://www.tyjrchina.org.cn";

    public static void main(String[] args) {
        try {
            Document doc = Jsoup.connect(URL).get();
            Elements newsItems = doc.select(".news-list li"); // 假设新闻列表项的类名为 .news-list li

            List<News> newsList = new ArrayList<>();

            for (Element item : newsItems) {
                String title = item.select("a").text();
                String href = item.select("a").attr("href");
                String publishTime = item.select(".time").text(); // 假设发布时间的类名为 .time

                // 获取文章详情
                String articleUrl = BASE_URL + href;
                Document articleDoc = Jsoup.connect(articleUrl).get();
                String content = articleDoc.select(".content").html(); // 假设文章内容的类名为 .content

                // 处理相对图片地址
                content = convertRelativeImagesToAbsolute(content, BASE_URL);

                News news = new News(title, publishTime, content);
                newsList.add(news);
            }

            // 打印抓取结果
            for (News news : newsList) {
                System.out.println("标题: " + news.getTitle());
                System.out.println("发布时间: " + news.getPublishTime());
                System.out.println("内容: " + news.getContent());
                System.out.println("------------------------------");
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static String convertRelativeImagesToAbsolute(String html, String baseUrl) {
        Document doc = Jsoup.parse(html);
        Elements imgTags = doc.select("img");

        for (Element img : imgTags) {
            String src = img.attr("src");
            if (!src.startsWith("http")) {
                img.attr("src", baseUrl + src);
            }
        }

        return doc.body().html();
    }

    static class News {
        private String title;
        private String publishTime;
        private String content;

        public News(String title, String publishTime, String content) {
            this.title = title;
            this.publishTime = publishTime;
            this.content = content;
        }

        public String getTitle() {
            return title;
        }

        public String getPublishTime() {
            return publishTime;
        }

        public String getContent() {
            return content;
        }
    }
}
```

