    private void handleClient(Socket socket) {
        try (InputStream inputStream = socket.getInputStream()) {
            byte[] buffer = new byte[1024 * 1024];
            int bytesRead;
            ByteBuffer frameBuffer = ByteBuffer.allocate(1024 * 1024);

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                frameBuffer.put(buffer, 0, bytesRead);
                frameBuffer.flip();

                // 假设客户端发送的是完整的NAL单元，这里简单地以长度为分隔符
                if (frameBuffer.remaining() >= 4) {
                    int length = frameBuffer.getInt();
                    if (frameBuffer.remaining() >= length) {
                        byte[] frameData = new byte[length];
                        frameBuffer.get(frameData);
                        decodeAndDisplay(frameData);
                        frameBuffer.compact();
                    } else {
                        frameBuffer.flip();
                        break;
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void decodeAndDisplay(byte[] frameData) {
        try {
            Picture picture = MPSDemuxer.readPictureWithDemuxer(ByteBuffer.wrap(frameData), null, null, null);
            java.awt.image.BufferedImage bufferedImage = AWTUtil.toBufferedImage(picture);
            PixelWriter pixelWriter = writableImage.getPixelWriter();
            for (int y = 0; y < bufferedImage.getHeight(); y++) {
                for (int x = 0; x < bufferedImage.getWidth(); x++) {
                    pixelWriter.setArgb(x, y, bufferedImage.getRGB(x, y));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

