    private void startServer() {
        try {
            serverSocket = new ServerSocket(12345);
            chatArea.append("客服端已启动，等待用户连接...\n");

            new Thread(new Runnable() {
                @Override
                public void run() {
                    while (true) {
                        try {
                            Socket socket = serverSocket.accept();
                            BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                            String username = in.readLine();
                            chatArea.append("新用户连接: " + username + "\n");

                            ClientHandler handler = new ClientHandler(socket, username);
                            clients.put(username, handler);
                            handler.start();

                        } catch (IOException e) {
                            chatArea.append("接受连接失败\n");
                        }
                    }
                }
            }).start();

        } catch (IOException e) {
            chatArea.append("无法启动客服端\n");
        }
    }

    private class ClientHandler extends Thread {
        private Socket socket;
        private String username;
        private PrintWriter out;
        private BufferedReader in;
        private File chatFile;

        public ClientHandler(Socket socket, String username) {
            this.socket = socket;
            this.username = username;
            chatFile = new File(username + "_chat.txt");
        }

        @Override
        public void run() {
            try {
                out = new PrintWriter(socket.getOutputStream(), true);
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));

                if (chatFile.exists()) {
                    BufferedReader fileReader = new BufferedReader(new FileReader(chatFile));
                    String line;
                    while ((line = fileReader.readLine()) != null) {
                        out.println(line);
                    }
                    fileReader.close();
                }

                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    if (inputLine.startsWith("IMAGE:")) {
                        String fileName = inputLine.substring(6);
                        receiveImage(fileName);
                    } else {
                        chatArea.append(username + ": " + inputLine + "\n");
                        appendToFile(username + ": " + inputLine);
                        out.println("客服: 已收到您的消息");
                    }
                }
            } catch (IOException e) {
                chatArea.append(username + " 已断开连接\n");
            } finally {
                clients.remove(username);
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void receiveImage(String fileName) throws IOException {
            FileOutputStream fos = new FileOutputStream(fileName);
            InputStream is = socket.getInputStream();
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
            fos.close();
            chatArea.append(username + ": [图片] " + fileName + "\n");
            appendToFile(username + ": [图片] " + fileName);
        }

        private void appendToFile(String message) throws IOException {
            FileWriter fw = new FileWriter(chatFile, true);
            fw.write(message + "\n");
            fw.close();
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                new Server();
            }
        });
    }
