package com.example.dao;

import com.example.model.Customer;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class CustomerDao {
    private Connection conn;

    public CustomerDao() {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/customer_db", "root", "password");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void addCustomer(Customer customer) {
        String sql = "INSERT INTO customer (unit1, unit2, unit3, name, phone, mobile, qq, email) VALUES (?, ?, ?, ?, ?, ?, ?, ?)";
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, customer.getUnit1());
            pstmt.setString(2, customer.getUnit2());
            pstmt.setString(3, customer.getUnit3());
            pstmt.setString(4, customer.getName());
            pstmt.setString(5, customer.getPhone());
            pstmt.setString(6, customer.getMobile());
            pstmt.setString(7, customer.getQq());
            pstmt.setString(8, customer.getEmail());
            pstmt.executeUpdate();
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }

    public List<Customer> queryCustomers(String name, String unit1, String unit2, String unit3) {
        List<Customer> customers = new ArrayList<>();
        StringBuilder sql = new StringBuilder("SELECT * FROM customer WHERE 1=1");
        if (name != null && !name.isEmpty()) {
            sql.append(" AND name LIKE ?");
        }
        if (unit1 != null && !unit1.isEmpty()) {
            sql.append(" AND unit1 = ?");
        }
        if (unit2 != null && !unit2.isEmpty()) {
            sql.append(" AND unit2 = ?");
        }
        if (unit3 != null && !unit3.isEmpty()) {
            sql.append(" AND unit3 = ?");
        }

        try (PreparedStatement pstmt = conn.prepareStatement(sql.toString())) {
            int index = 1;
            if (name != null && !name.isEmpty()) {
                pstmt.setString(index++, "%" + name + "%");
            }
            if (unit1 != null && !unit1.isEmpty()) {
                pstmt.setString(index++, unit1);
            }
            if (unit2 != null && !unit2.isEmpty()) {
                pstmt.setString(index++, unit2);
            }
            if (unit3 != null && !unit3.isEmpty()) {
                pstmt.setString(index++, unit3);
            }

            ResultSet rs = pstmt.executeQuery();
            while (rs.next()) {
                Customer customer = new Customer();
                customer.setId(rs.getInt("id"));
                customer.setUnit1(rs.getString("unit1"));
                customer.setUnit2(rs.getString("unit2"));
                customer.setUnit3(rs.getString("unit3"));
                customer.setName(rs.getString("name"));
                customer.setPhone(rs.getString("phone"));
                customer.setMobile(rs.getString("mobile"));
                customer.setQq(rs.getString("qq"));
                customer.setEmail(rs.getString("email"));
                customers.add(customer);
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
        return customers;
    }

    // 其他方法如更新、删除等...
}
```

#### 3.3 Controller层 (`CustomerServlet.java`)

```java
package com.example.controller;

import com.example.dao.CustomerDao;
import com.example.model.Customer;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.List;

@WebServlet("/CustomerServlet")
public class CustomerServlet extends HttpServlet {
    private CustomerDao customerDao = new CustomerDao();

    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        doGet(request, response);
    }

    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String action = request.getParameter("action");
        if ("add".equals(action)) {
            addCustomer(request, response);
        } else if ("query".equals(action)) {
            queryCustomers(request, response);
        }
    }

    private void addCustomer(HttpServletRequest request, HttpServletResponse response) throws IOException {
        Customer customer = new Customer();
        customer.setUnit1(request.getParameter("unit1"));
        customer.setUnit2(request.getParameter("unit2"));
        customer.setUnit3(request.getParameter("unit3"));
        customer.setName(request.getParameter("name"));
        customer.setPhone(request.getParameter("phone"));
        customer.setMobile(request.getParameter("mobile"));
        customer.setQq(request.getParameter("qq"));
        customer.setEmail(request.getParameter("email"));
        customerDao.addCustomer(customer);
        response.sendRedirect("queryCustomer.jsp");
    }

    private void queryCustomers(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String name = request.getParameter("name");
        String unit1 = request.getParameter("unit1");
        String unit2 = request.getParameter("unit2");
        String unit3 = request.getParameter("unit3");
        List<Customer> customers = customerDao.queryCustomers(name, unit1, unit2, unit3);
        request.setAttribute("customers", customers);
        request.getRequestDispatcher("queryCustomer.jsp").forward(request, response);
    }
}
```

