```java
import com.xuggle.mediatool.IMediaWriter;
import com.xuggle.mediatool.ToolFactory;
import com.xuggle.xuggler.ICodec;
import com.xuggle.xuggler.IPixelFormat;
import com.xuggle.xuggler.IVideoPicture;
import com.xuggle.xuggler.video.ConverterFactory;
import com.xuggle.xuggler.video.IConverter;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;

public class ImageToH264Encoder {

    public static byte[] encodeImageToH264(BufferedImage image, int width, int height) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        IMediaWriter writer = ToolFactory.makeWriter(baos);

        // 设置编码参数
        writer.addVideoStream(0, 0, ICodec.ID.CODEC_ID_H264, width, height);

        // 将BufferedImage转换为IVideoPicture
        IConverter converter = ConverterFactory.createConverter(image, IPixelFormat.Type.YUV420P, width, height);
        IVideoPicture picture = converter.toPicture(image, (long) 0);

        // 写入视频帧
        writer.encodeVideo(0, picture, 0, 0);

        // 刷新缓冲区
        writer.flush();
        writer.close();

        return baos.toByteArray();
    }

    public static void main(String[] args) throws IOException {
        BufferedImage image = ImageIO.read(new File("input.jpg"));
        byte[] h264Data = encodeImageToH264(image, image.getWidth(), image.getHeight());
        System.out.println("H.264 encoded data length: " + h264Data.length);
    }
}
