```java
import org.jcodec.codecs.h264.H264Decoder;
import org.jcodec.common.model.Picture;
import org.jcodec.scale.AWTUtil;
import javafx.application.Application;
import javafx.application.Platform;
import javafx.scene.Scene;
import javafx.scene.image.ImageView;
import javafx.scene.layout.StackPane;
import javafx.stage.Stage;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class H264Server extends Application {

    private ImageView imageView;
    private ExecutorService executorService = Executors.newSingleThreadExecutor();

    public static void main(String[] args) {
        launch(args);
    }

    @Override
    public void start(Stage primaryStage) {
        primaryStage.setTitle("H.264 Video Stream");
        imageView = new ImageView();
        StackPane root = new StackPane();
        root.getChildren().add(imageView);
        primaryStage.setScene(new Scene(root, 800, 600));
        primaryStage.show();

        executorService.submit(() -> {
            try (ServerSocket serverSocket = new ServerSocket(12345)) {
                System.out.println("Server started. Waiting for client...");
                while (true) {
                    Socket socket = serverSocket.accept();
                    System.out.println("Client connected: " + socket.getInetAddress());
                    handleClient(socket);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }

    private void handleClient(Socket socket) {
        try (InputStream inputStream = socket.getInputStream()) {
            byte[] buffer = new byte[1024 * 1024];
            int bytesRead;
            H264Decoder decoder = new H264Decoder();

            while ((bytesRead = inputStream.read(buffer)) != -1) {
                byte[] frameData = new byte[bytesRead];
                System.arraycopy(buffer, 0, frameData, 0, bytesRead);

                Picture picture = decoder.decodeFrame(frameData, 0);
                if (picture != null) {
                    final javafx.scene.image.Image image = AWTUtil.toFXImage(picture);
                    Platform.runLater(() -> imageView.setImage(image));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void stop() {
        executorService.shutdown();
    }
}
```

