import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.Socket;

public class Client {
    private Socket serverSocket;
    private ItemEffectModel itemEffectModel;

    public Client(String host, int port) {
        try {
            serverSocket = new Socket(host, port);
            itemEffectModel = new ItemEffectModel(); // Инициализация модели
            new Thread(this::listenForCommands).start(); // Поток для прослушивания
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    // Поток для приема команд от сервера
    private void listenForCommands() {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(serverSocket.getInputStream()))) {
            String inputLine;
            while ((inputLine = in.readLine()) != null) {
                JSONObject command = new JSONObject(inputLine);
                String cmd = command.getString("command");
                JSONArray args = command.getJSONArray("args");

                if (cmd.equals("set_remaining_time")) {
                    int entityId = args.getInt(0);
                    int remainingTime = args.getInt(1);
                    itemEffectModel.setRemaining(entityId, remainingTime);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        new Client("localhost", 12345);
    }
}

class ItemEffectModel {
    public void setRemaining(int entityId, int remainingTime) {
