    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-data-redis</artifactId>
    </dependency>

    <!-- Spring Boot Starter Actuator (Optional, for health checks) -->
    <dependency>
        <groupId>org.springframework.boot</groupId>
        <artifactId>spring-boot-starter-actuator</artifactId>
    </dependency>
</dependencies>
```

---

### **Application Configuration**

**1. Configure Redis in `application.yml`:**
```yaml
spring:
  redis:
    host: localhost
    port: 6379
```

**2. Configure Bucket4j with Redis in a Configuration Class:**
```java
import io.github.bucket4j.distributed.proxy.ProxyManager;
import io.github.bucket4j.redis.jredis.CasBasedProxyManager;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.GenericToStringSerializer;

@Configuration
public class Bucket4jConfig {

    @Value("${rate-limit.api.capacity}")
    private int capacity;

    @Value("${rate-limit.api.refill-tokens}")
    private int refillTokens;

    @Value("${rate-limit.api.refill-duration}")
    private int refillDuration;

    @Bean
    public RedisTemplate<String, Long> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Long> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        template.setValueSerializer(new GenericToStringSerializer<>(Long.class));
        return template;
    }

    @Bean
    public ProxyManager<String> bucket4jProxyManager(RedisTemplate<String, Long> redisTemplate) {
        return new CasBasedProxyManager<>(
                redisTemplate.getConnectionFactory(),
                (k, v) -> redisTemplate.opsForValue().set(k, v),
                redisTemplate::opsForValue
        );
    }
}
```

**3. Create a RateLimiter Service:**
```java
import io.github.bucket4j.Bucket;
import io.github.bucket4j.ConsumptionProbe;
import io.github.bucket4j.distributed.proxy.ProxyManager;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

import java.time.Duration;

@Service
public class RateLimiterService {

    private final ProxyManager<String> bucket4jProxyManager;

    public RateLimiterService(ProxyManager<String> bucket4jProxyManager) {
        this.bucket4jProxyManager = bucket4jProxyManager;
    }

    public void rateLimit(String apiKey) {
        Bucket bucket = bucket4jProxyManager.builder()
                .addLimit(limit -> limit
                        .capacity(10) // Max 10 requests
                        .refillGreedy(5, Duration.ofMinutes(1)) // Refill 5 tokens every minute
                        .build()
                )
                .build(apiKey);

        ConsumptionProbe probe = bucket.tryConsumeAndWithoutRemainingTokens(1);
        if (!probe.isConsumed()) {
            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS, "Rate limit exceeded");
        }
    }
}
```

**4. Create a Controller with Rate Limiting:**
```java
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class ApiController {

    private final RateLimiterService rateLimiterService;

    public ApiController(RateLimiterService rateLimiterService) {
        this.rateLimiterService = rateLimiterService;
    }

    @GetMapping("/resource")
    public String getResource(@RequestHeader("X-API-KEY") String apiKey) {
        rateLimiterService.rateLimit(apiKey);
        return "Resource accessed successfully!";
    }
}
```

---

### **How It Works**
1. **Redis as Storage**: Bucket4j uses Redis to store the rate-limiting state. This ensures that all instances of your application (running in different containers) share the same rate-limiting state.
2. **Distributed Rate Limiting**: When an API request comes in, Bucket4j checks the Redis-backed bucket for the API key. If the bucket has tokens available, the request is allowed; otherwise, it's rejected with a `429 Too Many Requests` status.
3. **Scalability**: Since Redis is a distributed store, this setup works seamlessly across multiple containers in a Kubernetes cluster.

---

### **Docker and Kubernetes Setup**
1. **Redis Deployment**: Deploy a Redis instance in your Kubernetes cluster.
2. **Application Deployment**: Package your Spring Boot application into a Docker container and deploy it to Kubernetes. Ensure the application can connect to the Redis instance.

Example Redis deployment YAML:
```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: redis
spec:
  replicas: 1
  selector:
    matchLabels:
      app: redis
  template:
    metadata:
      labels:
        app: redis
    spec:
      containers:
      - name: redis
        image: redis:latest
        ports:
        - containerPort: 6379
---
apiVersion: v1
kind: Service
metadata:
  name: redis
spec:
  ports:
  - port: 6379
  selector:
    app: redis
```

---

### **Testing**
1. Start your Spring Boot application.
2. Send multiple requests to the `/api/resource` endpoint with an `X-API-KEY` header.
3. Once the rate limit is exceeded, you'll receive a `429 Too Many Requests` response.

Example curl request:
```bash
curl -H "X-API-KEY: 12345" http://localhost:8080/api/resource
```

This setup ensures distributed rate limiting across all instances of your application in a Kubernetes cluster.

