import java.util.Hashtable;
import java.util.Properties;
import javax.mail.*;
import javax.mail.internet.MimeMessage;
import javax.mail.search.SubjectTerm;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ImapMailReceiver {

    public static void main(String[] args) {
        // IMAP server details
        String host = "imap.example.com";
        String username = "your_username";
        String password = "your_password";

        // Folder to fetch emails from (e.g., "INBOX")
        String folderName = "INBOX";

        // Hashtable to store subject number and message content
        Hashtable<String, String> mailData = new Hashtable<>();

        // Setup properties for the IMAP session
        Properties properties = new Properties();
        properties.put("mail.imap.host", host);
        properties.put("mail.imap.port", "993");
        properties.put("mail.imap.ssl.enable", "true");

        // Create a Session object
        Session session = Session.getInstance(properties);

        try {
            // Connect to the IMAP server
            Store store = session.getStore("imaps");
            store.connect(host, username, password);

            // Open the folder
            Folder folder = store.getFolder(folderName);
            folder.open(Folder.READ_ONLY);

            // Fetch all messages
            Message[] messages = folder.getMessages();

            for (Message message : messages) {
                if (message instanceof MimeMessage) {
                    MimeMessage mimeMessage = (MimeMessage) message;

                    // Extract subject
                    String subject = mimeMessage.getSubject();
                    // Assuming the subject contains a number, extract it
                    String subjectNumber = extractNumberFromSubject(subject);

                    if (subjectNumber != null) {
                        // Extract message content
                        String messageContent = extractMessageContent(mimeMessage);

                        // Store in Hashtable
                        mailData.put(subjectNumber, messageContent);
                    }
                }
            }

            // Close the folder and store
            folder.close(false);
            store.close();

            // Print the Hashtable contents
            for (String key : mailData.keySet()) {
                System.out.println("Subject Number: " + key + ", Message: " + mailData.get(key));
            }

        } catch (MessagingException | IOException e) {
            e.printStackTrace();
        }
    }

    // Helper method to extract the number from the subject
    private static String extractNumberFromSubject(String subject) {
        // Simple extraction assuming the subject contains a number
        // You may need to adjust this based on your subject format
        try {
            String[] parts = subject.split("\\s+");
            for (String part : parts) {
                if (part.matches("\\d+")) {
                    return part;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        return null;
    }

    // Helper method to extract the message content
    private static String extractMessageContent(MimeMessage message) throws IOException, MessagingException {
        StringBuilder content = new StringBuilder();
        if (message.isMimeType("text/plain")) {
            content.append(message.getContent().toString());
        } else if (message.isMimeType("multipart/*")) {
            Multipart multipart = (Multipart) message.getContent();
            for (int i = 0; i < multipart.getCount(); i++) {
                BodyPart bodyPart = multipart.getBodyPart(i);
                if (bodyPart.isMimeType("text/plain")) {
                    content.append(bodyPart.getContent().toString());
                }
            }
        }
        return content.toString().trim();
    }
}
