     // 编码YUV帧
     x264_picture_t pic_in = x264_picture_alloc();
     pic_in.img.i_csp = X264_CSP_I420;
     pic_in.img.plane[0] = yuvFrameAddress; // Y分量
     pic_in.img.plane[1] = yuvFrameAddress + width * height; // U分量
     pic_in.img.plane[2] = yuvFrameAddress + width * height * 5 / 4; // V分量

     x264_nal_t[] nals = new x264_nal_t[1];
     x264_picture_t pic_out = new x264_picture_t();
     int result = x264_encoder_encode(encoder, nals, nals.length, pic_in, pic_out);

     // 提取H.264 NAL单元（字节流）
     byte[] encodedFrame = nals[0].p_payload;
     ```

### 3. **WebSocket实时传输**
   - **使用库**：`Java WebSocket API`（JSR 356）或`Spring WebSocket`。
