@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<LoginResponse> login(
            @Valid @RequestBody LoginRequest request,
            HttpServletRequest httpRequest) {

        return ResponseEntity.ok(authService.authenticate(request, httpRequest));
    }
}

// AuthService.java (服务层)
@Service
@RequiredArgsConstructor
public class AuthService {

    private final UserRepository userRepository;
    private final JwtTokenProvider tokenProvider;
    private final PasswordEncoder passwordEncoder;
    private final RedisTemplate<String, Object> redisTemplate;

    public LoginResponse authenticate(LoginRequest request, HttpServletRequest httpRequest) {
        // 复杂请求处理逻辑
        validateRequestFrequency(request.getUsername(), httpRequest);

        User user = userRepository.findByUsername(request.getUsername())
                .orElseThrow(() -> new UnauthorizedException("用户名或密码错误"));

        validatePassword(request.getPassword(), user);
        validateAccountStatus(user);

        // 更新登录信息
        updateLoginInfo(user, httpRequest);

        // 生成Token
        String token = tokenProvider.createToken(user.getId(), user.getUsername());

        // 保存登录会话
        saveLoginSession(user, token);

        return buildLoginResponse(user, token);
    }

    private void validateRequestFrequency(String username, HttpServletRequest request) {
        String ip = getClientIP(request);
        String key = "login_attempt:" + ip + ":" + username;

        int attempts = (int) redisTemplate.opsForValue().increment(key);
        if (attempts > 5) {
            Long expire = redisTemplate.getExpire(key);
            if (expire == null || expire > 0) {
                throw new TooManyRequestsException("请求过于频繁，请稍后再试");
            }
        }

        redisTemplate.expire(key, 1, TimeUnit.MINUTES);
    }

    private void validatePassword(String rawPassword, User user) {
        if (!passwordEncoder.matches(rawPassword + user.getSalt(), user.getPassword())) {
            recordFailedAttempt(user);
            throw new UnauthorizedException("用户名或密码错误");
        }
    }

    private void validateAccountStatus(User user) {
        // 添加账户状态检查逻辑（如锁定、过期等）
    }

    private void updateLoginInfo(User user, HttpServletRequest request) {
        user.setLastLogin(LocalDateTime.now());
        userRepository.save(user);

        // 记录登录日志
        logLogin(user, request);
    }

    private void saveLoginSession(User user, String token) {
        redisTemplate.opsForValue().set(
                "session:" + user.getId(), 
                token, 
                1, 
                TimeUnit.DAYS);
    }

    private LoginResponse buildLoginResponse(User user, String token) {
        return LoginResponse.builder()
                .token(token)
                .userId(user.getId())
                .username(user.getUsername())
                .build();
    }

    // IP获取工具方法
    private String getClientIP(HttpServletRequest request) {
        // 处理反向代理情况
        String ip = request.getHeader("X-Forwarded-For");
        if (ip == null || ip.length() == 0 || "unknown".equalsIgnoreCase(ip)) {
            ip = request.getHeader("Proxy-Client-IP");
        }
        if (ip == null || ip.length() == 0 || "unknown".equalsIgnoreCase(ip)) {
            ip = request.getHeader("WL-Proxy-Client-IP");
        }
        return ip != null ? ip : request.getRemoteAddr();
    }
}

// JwtTokenProvider.java (JWT工具类)
@Component
@RequiredArgsConstructor
public class JwtTokenProvider {

    @Value("${jwt.secret}")
    private String jwtSecret;

    @Value("${jwt.expiration}")
    private int jwtExpirationMs;

    public String createToken(Long id, String username) {
        return Jwts.builder()
                .setSubject(username)
                .claim("uid", id)
                .setIssuedAt(new Date())
                .setExpiration(new Date((new Date()).getTime() + jwtExpirationMs))
                .signWith(SignatureAlgorithm.HS512, jwtSecret)
                .compact();
    }

    // 其他JWT相关方法...
}

// 异常处理类
