import java.io.*;
import java.net.Socket;

public class Client {
    private Socket socket;
    private ObjectOutputStream out;
    private ObjectInputStream in;
    private ClientGUI gui;
    private String userId;

    public Client(String userId, String serverAddress, int port) {
        this.userId = userId;
        try {
            socket = new Socket(serverAddress, port);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());
            gui = new ClientGUI(this);

            new Thread(() -> {
                try {
                    while (true) {
                        Message message = (Message) in.readObject();
                        handleMessage(message);
                    }
                } catch (EOFException e) {
                    System.out.println("Server closed the connection.");
                } catch (IOException | ClassNotFoundException e) {
                    e.printStackTrace();
                }
            }).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void handleMessage(Message message) {
        if (message.getType() == MessageType.TEXT) {
            gui.appendMessage("客服: " + message.getContent());
        } else if (message.getType() == MessageType.BUSY) {
            gui.appendMessage("客服忙，请稍后再试。");
        }
    }

    public void sendMessage(String content) {
        Message message = new Message(MessageType.TEXT, content);
        try {
            out.writeObject(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void sendFile(File file) {
        try {
            byte[] fileData = java.nio.file.Files.readAllBytes(file.toPath());
            Message message = new Message(MessageType.FILE, "", fileData, file.getName());
            out.writeObject(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void sendImage(File file) {
        try {
            byte[] fileData = java.nio.file.Files.readAllBytes(file.toPath());
            Message message = new Message(MessageType.IMAGE, "", fileData, file.getName());
            out.writeObject(message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        new Client("user1", "localhost", 12345);
    }
}
