import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;

public class Server {
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clients = new HashMap<>();
    private ServerGUI gui;

    public Server(int port) {
        try {
            serverSocket = new ServerSocket(port);
            gui = new ServerGUI(this);

            new Thread(() -> {
                try {
                    while (true) {
                        Socket socket = serverSocket.accept();
                        new ClientHandler(socket);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    class ClientHandler implements Runnable {
        private Socket socket;
        private ObjectOutputStream out;
        private ObjectInputStream in;
        private String userId;
        private boolean isChatting = false;

        public ClientHandler(Socket socket) {
            this.socket = socket;
            try {
                out = new ObjectOutputStream(socket.getOutputStream());
                in = new ObjectInputStream(socket.getInputStream());

                Message request = (Message) in.readObject();
                if (request.getType() == MessageType.REQUEST) {
                    this.userId = request.getContent();
                    clients.put(userId, this);
                    gui.addClient(userId);
                }

                new Thread(this).start();
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }
        }

        @Override
        public void run() {
            try {
                while (true) {
                    Message message = (Message) in.readObject();
                    handleMessage(message);
                }
            } catch (EOFException e) {
                System.out.println("Client " + userId + " disconnected.");
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }
        }

        private void handleMessage(Message message) {
            if (message.getType() == MessageType.TEXT || message.getType() == MessageType.FILE || message.getType() == MessageType.IMAGE) {
                // 保存聊天记录到文件
                saveChatHistory(message);
                // 转发消息给客服
                // 这里简化处理，实际应根据客服选择转发
            }
        }

        public void startChat() {
            isChatting = true;
            // 加载聊天记录
            loadChatHistory();
        }

        public void sendBusyMessage() {
            Message busyMessage = new Message(MessageType.BUSY, "客服忙，请稍后再试。");
            try {
                out.writeObject(busyMessage);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void saveChatHistory(Message message) {
            try (FileWriter writer = new FileWriter(userId + "_chat.txt", true)) {
                writer.write(message.toString() + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void loadChatHistory() {
            try (BufferedReader reader = new BufferedReader(new FileReader(userId + "_chat.txt"))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    // 将聊天记录显示在客服界面
                    gui.appendMessage(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        new Server(12345);
    }
}
