import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;

public class ImageToH264Converter {

    public static byte[] convertImageToH264(String imagePath) throws IOException {
        // 读取图片
        BufferedImage image = ImageIO.read(new File(imagePath));

        // 创建临时文件用于存储H.264流
        File tempFile = File.createTempFile("h264", ".mp4");
        tempFile.deleteOnExit();

        // 使用JCodec将图片编码为H.264
        try (AWTSequenceEncoder encoder = AWTSequenceEncoder.createSequenceEncoder(NIOUtils.writableChannel(tempFile), 1)) {
            Picture picture = AWTUtil.fromBufferedImage(image);
            encoder.encodeImage(picture);
        }

        // 读取生成的H.264流
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream()) {
            NIOUtils.copy(NIOUtils.readableChannel(tempFile), bos);
