package com.example;

import org.apache.doris.udf.ScalarFunction;
import org.apache.doris.udf.FunctionContext;
import javax.xml.bind.JAXBContext;
import javax.xml.bind.Unmarshaller;
import java.io.StringReader;

public class XmlParserUDF extends ScalarFunction {

    @Override
    public String evaluate(FunctionContext context, String xmlString) {
        if (xmlString == null || xmlString.isEmpty()) {
            return null;
        }

        try {
            // 假设我们有一个简单的 XML 模型类，例如 Person
            JAXBContext jaxbContext = JAXBContext.newInstance(Person.class);
            Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();
            Person person = (Person) unmarshaller.unmarshal(new StringReader(xmlString));

            // 返回解析后的结果，例如姓名
            return person.getName();
        } catch (Exception e) {
            throw new RuntimeException("Failed to parse XML", e);
        }
    }
}
```

