```java
import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.concurrent.RecursiveTask;

public class QuickSortMultiThreading extends RecursiveTask<Void> {

    private int start, end;
    private int[] arr;

    /**
     * Finding random pivot and partition the array on the pivot.
     * There are many different partitioning algorithms.
     * @param start
     * @param end
     * @param arr
     * @return
     */
    private int partition(int start, int end, int[] arr) {
        int i = start, j = end;

        // Decide random pivot
        int pivot = new Random().nextInt(j - i + 1) + i;

        // Swap the pivot with the end element of the array
        int temp = arr[pivot];
        arr[pivot] = arr[end];
        arr[end] = temp;

        // Start partitioning
        while (i <= j) {
            if (arr[i] <= arr[end]) {
                i++;
                continue;
            }
            if (arr[j] >= arr[end]) {
                j--;
                continue;
            }
            temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i++;
            j--;
        }

        // Swap pivot to its correct position
        temp = arr[i - 1];
        arr[i - 1] = arr[end];
        arr[end] = temp;
        return i - 1;
    }

    // Constructor to initialize the array and range
    public QuickSortMultiThreading(int start, int end, int[] arr) {
        this.arr = arr;
        this.start = start;
        this.end = end;
    }

    @Override
    protected Void compute() {
        // Base case
        if (start >= end) {
            return null;
        }

        // Find partition
        int p = partition(start, end, arr);

        // Divide array into two subproblems
        QuickSortMultiThreading left = new QuickSortMultiThreading(start, p - 1, arr);
        QuickSortMultiThreading right = new QuickSortMultiThreading(p + 1, end, arr);

        // Execute left subproblem as a separate thread
        left.fork();

        // Directly compute the right subproblem
        right.compute();

        // Wait until the left thread completes
        left.join();

        // We don't need to return anything
        return null;
    }

    // Driver Code
    public static void main(String[] args) {
        int n = 7;
        int[] arr = { 54, 64, 95, 82, 12, 32, 63 };

        // ForkJoinPool to manage thread creation based on available resources
        ForkJoinPool pool = ForkJoinPool.commonPool();

        // Start the first task in the ForkJoinPool for the range [0, n-1]
        pool.invoke(new QuickSortMultiThreading(0, n - 1, arr));

        // Print sorted elements
        for (int i = 0; i < n; i++) {
            System.out.print(arr[i] + " ");
        }
    }
}
