```java
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import javax.xml.stream.XMLOutputFactory;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamWriter;
import java.io.StringWriter;

public class JsonToXmlConverter {

    private static final ObjectMapper objectMapper = new ObjectMapper();

    public static String convertJsonToXml(String json) throws Exception {
        JsonNode rootNode = objectMapper.readTree(json);
        StringWriter stringWriter = new StringWriter();
        XMLOutputFactory xmlOutputFactory = XMLOutputFactory.newInstance();
        XMLStreamWriter xmlStreamWriter = xmlOutputFactory.createXMLStreamWriter(stringWriter);

        xmlStreamWriter.writeStartDocument("1.0", "UTF-8");
        writeNode(rootNode, xmlStreamWriter, "root");
        xmlStreamWriter.writeEndDocument();
        xmlStreamWriter.flush();
        xmlStreamWriter.close();

        return stringWriter.toString();
    }

    private static void writeNode(JsonNode node, XMLStreamWriter xmlStreamWriter, String nodeName) throws XMLStreamException {
        if (node.isObject()) {
            xmlStreamWriter.writeStartElement(nodeName);
            node.fields().forEachRemaining(entry -> {
                try {
                    writeNode(entry.getValue(), xmlStreamWriter, entry.getKey());
                } catch (XMLStreamException e) {
                    throw new RuntimeException(e);
                }
            });
            xmlStreamWriter.writeEndElement();
        } else if (node.isArray()) {
            node.elements().forEachRemaining(childNode -> {
                try {
                    writeNode(childNode, xmlStreamWriter, nodeName + "Item");
                } catch (XMLStreamException e) {
                    throw new RuntimeException(e);
                }
            });
        } else if (node.isTextual() || node.isNumber() || node.isBoolean()) {
            xmlStreamWriter.writeStartElement(nodeName);
            xmlStreamWriter.writeCharacters(node.asText());
            xmlStreamWriter.writeEndElement();
        } else if (node.isNull()) {
            xmlStreamWriter.writeEmptyElement(nodeName);
        }
    }

    public static void main(String[] args) {
        String json = "{\n" +
                "  \"name\": \"John Doe\",\n" +
                "  \"age\": 30,\n" +
                "  \"address\": {\n" +
                "    \"street\": \"123 Main St\",\n" +
                "    \"city\": \"Anytown\",\n" +
                "    \"state\": \"CA\",\n" +
                "    \"postalCode\": \"12345\"\n" +
                "  },\n" +
                "  \"phoneNumbers\": [\n" +
                "    {\n" +
                "      \"type\": \"home\",\n" +
                "      \"number\": \"555-555-1234\"\n" +
                "    },\n" +
                "    {\n" +
                "      \"type\": \"work\",\n" +
                "      \"number\": \"555-555-5678\"\n" +
                "    }\n" +
                "  ]\n" +
                "}";

        try {
            String xml = convertJsonToXml(json);
            System.out.println(xml);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

### 代码说明：
1. **ObjectMapper**: 用于将JSON字符串解析为`JsonNode`对象。
2. **XMLStreamWriter**: 用于生成XML格式的字符串。
3. **writeNode方法**: 递归地将`JsonNode`转换为XML格式。根据节点类型（对象、数组、文本等），生成相应的XML标签。

### 示例输出：
