import java.io.*;
import java.net.Socket;

public class ServerNetworkHandler implements Runnable {
    private Socket clientSocket;
    private HOTELIERServer server;

    public ServerNetworkHandler(Socket clientSocket, HOTELIERServer server) {
        this.clientSocket = clientSocket;
        this.server = server;
    }

    @Override
    public void run() {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
             PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true)) {

            String request;
            while ((request = in.readLine()) != null) {
                String[] parts = request.split(";");
                String response = "";

                switch (parts[0]) {
                    case "REGISTER":
                        response = server.register(parts[1], parts[2]);
                        break;
                    case "LOGIN":
                        response = server.login(parts[1], parts[2]);
                        break;
                    case "LOGOUT":
                        response = server.logout(parts[1]);
                        break;
                    case "SEARCH_HOTEL":
                        response = server.searchHotel(parts[1], parts[2]);
                        break;
                    case "SEARCH_ALL_HOTELS":
                        response = server.searchAllHotels(parts[1]);
                        break;
                    case "INSERT_REVIEW":
                        String[] singleScores = parts[5].split(" ");
                        int[] scores = new int[singleScores.length];
                        for (int i = 0; i < singleScores.length; i++) {
                            scores[i] = Integer.parseInt(singleScores[i]);
                        }
                        response = server.insertReview(parts[1], parts[2], parts[3], Integer.parseInt(parts[4]), scores);
                        break;
                    case "SHOW_BADGES":
                        response = server.showMyBadges(parts[1]);
                        break;
                    default:
                        response = "Comando non riconosciuto.";
                }

                out.println(response);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class ClientNetworkHandler {
    private String serverAddress;
    private int serverPort;

    public ClientNetworkHandler(String serverAddress, int serverPort) {
        this.serverAddress = serverAddress;
        this.serverPort = serverPort;
    }

    public String sendRequest(String request) {
        try (Socket socket = new Socket(serverAddress, serverPort);
             PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
             BufferedReader in = new BufferedReader(new InputStreamReader(socket.getInputStream()))) {

            out.println(request);
            return in.readLine();
        } catch (IOException e) {
            return "Errore di connessione al server.";
        }
    }
}
