```java
package com.example.androidtcpsslclient;

import android.os.AsyncTask;
import android.util.Log;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.Socket;
import java.net.UnknownHostException;
import javax.net.ssl.SSLSocket;
import javax.net.ssl.SSLSocketFactory;

public class TcpSslClient {

    private static final String TAG = TcpSslClient.class.getSimpleName();
    private static final String SERVER_HOST = "your.server.com"; // Replace with your server hostname or IP
    private static final int SERVER_PORT = 443; // Replace with your server port

    private SSLSocket socket;
    private boolean isConnected = false;

    public interface TcpSslClientListener {
        void onConnected();
        void onDisconnected();
        void onMessageReceived(String message);
        void onError(String error);
    }

    private TcpSslClientListener listener;

    public TcpSslClient(TcpSslClientListener listener) {
        this.listener = listener;
    }

    public void connect() {
        new ConnectTask().execute();
    }

    public void disconnect() {
        if (socket != null && !socket.isClosed()) {
            try {
                socket.close();
                isConnected = false;
                if (listener != null) {
                    listener.onDisconnected();
                }
            } catch (IOException e) {
                Log.e(TAG, "Error closing socket: " + e.getMessage());
            }
        }
    }

    public void sendMessage(String message) {
        if (isConnected) {
            new SendMessageTask().execute(message);
        } else {
            Log.e(TAG, "Not connected to server");
        }
    }

    private class ConnectTask extends AsyncTask<Void, Void, Boolean> {

        private Exception exception;

        @Override
        protected Boolean doInBackground(Void... voids) {
            try {
                SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
                socket = (SSLSocket) sslSocketFactory.createSocket(SERVER_HOST, SERVER_PORT);
                isConnected = true;
                return true;
            } catch (UnknownHostException e) {
                exception = e;
                return false;
            } catch (IOException e) {
                exception = e;
                return false;
            }
        }

        @Override
        protected void onPostExecute(Boolean success) {
            if (success) {
                if (listener != null) {
                    listener.onConnected();
                }
                new ReceiveMessageTask().execute();
            } else {
                if (listener != null) {
                    listener.onError("Connection error: " + exception.getMessage());
                }
            }
        }
    }

    private class SendMessageTask extends AsyncTask<String, Void, Void> {

        @Override
        protected Void doInBackground(String... messages) {
            String message = messages[0];
            try {
                OutputStream outputStream = socket.getOutputStream();
                outputStream.write(message.getBytes());
                outputStream.flush();
            } catch (IOException e) {
                Log.e(TAG, "Error sending message: " + e.getMessage());
            }
            return null;
        }
    }

    private class ReceiveMessageTask extends AsyncTask<Void, String, Void> {

        @Override
        protected Void doInBackground(Void... voids) {
            try {
                InputStream inputStream = socket.getInputStream();
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    String message = new String(buffer, 0, bytesRead);
                    publishProgress(message);
                }
            } catch (IOException e) {
                Log.e(TAG, "Error receiving message: " + e.getMessage());
            }
            return null;
        }

        @Override
        protected void onProgressUpdate(String... messages) {
            if (listener != null) {
                listener.onMessageReceived(messages[0]);
            }
        }
    }
}
