    public void setName(String name) { this.name = name; }

    public String getCourse() { return course; }
    public void setCourse(String course) { this.course = course; }

    public double getGpa() { return gpa; }
    public void setGpa(double gpa) { this.gpa = gpa; }

    @Override
    public String toString() {
        return "ID: " + id + ", Name: " + name + ", Course: " + course + ", GPA: " + gpa;
    }
}

// StudentManagementSystem class to manage student records
class StudentManagementSystem {
    private Map<Integer, Student> students;

    public StudentManagementSystem() {
        this.students = new HashMap<>();
    }

    // Add a student record
    public void addStudent(Student student) {
        if (!students.containsKey(student.getId())) {
            students.put(student.getId(), student);
            System.out.println("Student added successfully.");
        } else {
            System.out.println("Student with ID " + student.getId() + " already exists.");
        }
    }

    // Remove a student record
    public void removeStudent(int id) {
        if (students.containsKey(id)) {
            students.remove(id);
            System.out.println("Student removed successfully.");
        } else {
            System.out.println("Student with ID " + id + " not found.");
        }
    }

    // Update a student record
    public void updateStudent(int id, Student updatedStudent) {
        if (students.containsKey(id)) {
            students.put(id, updatedStudent);
            System.out.println("Student updated successfully.");
        } else {
            System.out.println("Student with ID " + id + " not found.");
        }
    }

    // Search for a student by ID
    public Student searchById(int id) {
        return students.getOrDefault(id, null);
    }

    // Search for students by name
    public List<Student> searchByName(String name) {
        List<Student> result = new ArrayList<>();
        for (Student student : students.values()) {
            if (student.getName().equalsIgnoreCase(name)) {
                result.add(student);
            }
        }
        return result;
    }

    // Generate a report of all students
    public void generateReport() {
        if (students.isEmpty()) {
            System.out.println("No student records found.");
        } else {
            System.out.println("Student Report:");
            for (Student student : students.values()) {
                System.out.println(student);
            }
        }
    }
}

