#### 3.2 客服端

```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;

public class Server extends JFrame implements ActionListener {
    private JTextArea chatArea;
    private JTextField messageField;
    private JButton sendButton, sendFileButton;
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clients = new HashMap<>();

    public Server() {
        setTitle("客服端");
        setSize(400, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(chatArea);
        add(scrollPane, BorderLayout.CENTER);

        JPanel bottomPanel = new JPanel();
        messageField = new JTextField(20);
        sendButton = new JButton("发送");
        sendFileButton = new JButton("发送文件");
        bottomPanel.add(messageField);
        bottomPanel.add(sendButton);
        bottomPanel.add(sendFileButton);
        add(bottomPanel, BorderLayout.SOUTH);

        sendButton.addActionListener(this);
        sendFileButton.addActionListener(this);

        try {
            serverSocket = new ServerSocket(1234);
            new Thread(() -> {
                while (true) {
                    try {
                        Socket socket = serverSocket.accept();
                        ClientHandler handler = new ClientHandler(socket);
                        clients.put(socket.getInetAddress().getHostAddress(), handler);
                        handler.start();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        if (e.getSource() == sendButton) {
            String message = messageField.getText();
            if (!message.isEmpty()) {
                for (ClientHandler handler : clients.values()) {
                    handler.sendMessage(message);
                }
                chatArea.append("客服: " + message + "\n");
                messageField.setText("");
            }
        } else if (e.getSource() == sendFileButton) {
            JFileChooser fileChooser = new JFileChooser();
            int result = fileChooser.showOpenDialog(this);
            if (result == JFileChooser.APPROVE_OPTION) {
                File file = fileChooser.getSelectedFile();
                for (ClientHandler handler : clients.values()) {
                    handler.sendFile(file);
                }
                chatArea.append("客服: [文件] " + file.getName() + "\n");
            }
        }
    }

    private class ClientHandler extends Thread {
        private Socket socket;
        private DataInputStream dis;
        private DataOutputStream dos;
        private String clientAddress;

        public ClientHandler(Socket socket) {
            this.socket = socket;
            this.clientAddress = socket.getInetAddress().getHostAddress();
            try {
                dis = new DataInputStream(socket.getInputStream());
                dos = new DataOutputStream(socket.getOutputStream());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void sendMessage(String message) {
            try {
                dos.writeUTF(message);
                dos.flush();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void sendFile(File file) {
            try {
                dos.writeUTF("FILE:" + file.getName());
                FileInputStream fis = new FileInputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    dos.write(buffer, 0, bytesRead);
                }
                dos.flush();
                fis.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        @Override
        public void run() {
            try {
                while (true) {
                    String message = dis.readUTF();
                    if (message.startsWith("IMAGE:")) {
                        String fileName = message.substring(6);
                        chatArea.append(clientAddress + ": [图片] " + fileName + "\n");
                        int bytesRead;
                        FileOutputStream fos = new FileOutputStream(fileName);
                        byte[] buffer = new byte[4096];
                        while ((bytesRead = dis.read(buffer)) > 0) {
                            fos.write(buffer, 0, bytesRead);
                        }
                        fos.close();
                    } else {
                        chatArea.append(clientAddress + ": " + message + "\n");
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
                clients.remove(clientAddress);
            }
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            Server server = new Server();
            server.setVisible(true);
        });
    }
}
```

