```python
from flask import Flask, redirect, request, session, url_for
import requests

app = Flask(__name__)
app.secret_key = 'your_secret_key_here'  # Replace with a secure secret key

# CAS Configuration
CAS_SERVER = 'https://cas.eduverse.edu'
CAS_LOGIN_URL = f'{CAS_SERVER}/login'
CAS_VALIDATE_URL = f'{CAS_SERVER}/serviceValidate'
CAS_LOGOUT_URL = f'{CAS_SERVER}/logout'
SERVICE_URL = 'https://your-app.eduverse.edu/callback'  # Replace with your app's callback URL

@app.route('/')
def index():
    if 'username' in session:
        return f'Hello, {session["username"]}! <a href="/logout">Logout</a>'
    return f'Welcome to Eduverse! <a href="{url_for("login")}">Login with CAS</a>'

@app.route('/login')
def login():
    return redirect(f'{CAS_LOGIN_URL}?service={SERVICE_URL}')

@app.route('/callback')
def callback():
    ticket = request.args.get('ticket')
    if not ticket:
        return redirect(url_for('index'))

    # Validate the ticket with CAS
    params = {
        'service': SERVICE_URL,
        'ticket': ticket
    }
    response = requests.get(CAS_VALIDATE_URL, params=params)

    if response.status_code == 200:
        from xml.etree import ElementTree as ET
        root = ET.fromstring(response.content)
        username = root.find('.//cas:user', namespaces={'cas': 'http://www.yale.edu/tp/cas'}).text
        session['username'] = username
        return redirect(url_for('index'))

    return 'Authentication failed. Please try again.'

@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(f'{CAS_LOGOUT_URL}?service={SERVICE_URL}')

if __name__ == '__main__':
    app.run(ssl_context='adhoc', debug=True)  # Use proper SSL in production
```

