        long startTime = System.currentTimeMillis();
        count(text);
        repeatedWords(text);
        longest(text);
        shortest(text);
        repeat(text);
        return System.currentTimeMillis() - startTime;
    }

    @Override
    public long analyzeMultiThreaded(String text) throws RemoteException {
        long startTime = System.currentTimeMillis();
        ExecutorService executor = Executors.newFixedThreadPool(5);
        Future<Integer> countFuture = executor.submit(() -> count(text));
        Future<List<String>> repeatedFuture = executor.submit(() -> repeatedWords(text));
        Future<String> longestFuture = executor.submit(() -> longest(text));
        Future<String> shortestFuture = executor.submit(() -> shortest(text));
        Future<Map<String, Integer>> repeatFuture = executor.submit(() -> repeat(text));

        try {
            countFuture.get();
            repeatedFuture.get();
            longestFuture.get();
            shortestFuture.get();
            repeatFuture.get();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }
        return System.currentTimeMillis() - startTime;
    }
}
