import com.ncs.security.service.AuthServiceImpl;
import com.ncs.security.model.AuthResult;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private AuthServiceImpl authService;

    @PostMapping("/login")
    public ResponseEntity<AuthResponse> login(@RequestBody AuthRequest authRequest) {
        AuthResult authResult = authService.auth(
                authRequest.getLogin(),
                authRequest.getPassword(),
                authRequest.getIp()
        );

        if (authResult.isValid()) {
            AuthResponse response = new AuthResponse();
            response.setToken(authResult.getToken().getToken());
            response.setValid(true);
            return ResponseEntity.ok(response);
        } else {
            AuthResponse response = new AuthResponse();
            response.setValid(false);
            response.setMessage(authResult.getMessage());
            return ResponseEntity.badRequest().body(response);
        }
    }
}
```

