### Исправленный код для сериализации и десериализации:

```java
import java.io.*;
import java.nio.charset.StandardCharsets;

public class FileUtils {

    public static void serializeA(String data, String filename) throws IOException {
        try (ObjectOutputStream outputStream = new ObjectOutputStream(new FileOutputStream(filename))) {
            outputStream.writeObject(data);
        }
    }

    public static Object deserializeA(String filename) throws IOException, ClassNotFoundException {
        try (ObjectInputStream inputStream = new ObjectInputStream(new FileInputStream(filename))) {
            return inputStream.readObject();
        }
    }

    public static void main(String[] args) {
        System.out.println("Введите строку на русском");
        var b = new java.util.Scanner(System.in, StandardCharsets.UTF_8.name()).nextLine();
        try {
            FileUtils.serializeA(b, "test.set");
            var a = (String) FileUtils.deserializeA("test.set");
            System.out.println("\"" + a + "\"");
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
```

