const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const vmcMenu = document.getElementById('vmcMenu');
const addLineBtn = document.getElementById('addLineBtn');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

let lines = []; // Stores drawn lines
let model = []; // Stores the 3D wireframe model
let gridPoints = []; // Stores grid snapping points

let camera = {
  position: [0, 0, 5],
  rotation: [0, 0],
  fov: 1000,
};

let mouse = { x: 0, y: 0 };
let isDragging = false;
let selectedPoint = null;

// Initialize grid points
function initGridPoints() {
  const size = 10;
  for (let x = -size; x <= size; x++) {
    for (let y = -size; y <= size; y++) {
      for (let z = -size; z <= size; z++) {
        gridPoints.push([x, y, z]);
      }
    }
  }
}

// Project 3D point to 2D
function project(point) {
  const [x, y, z] = point;
  const [cx, cy, cz] = camera.position;
  const [rx, ry] = camera.rotation;

  // Rotate around X axis
  const rotatedY = y * Math.cos(rx) - z * Math.sin(rx);
  const rotatedZ = y * Math.sin(rx) + z * Math.cos(rx);

  // Rotate around Y axis
  const rotatedX = x * Math.cos(ry) + rotatedZ * Math.sin(ry);
  const rotatedZ2 = -x * Math.sin(ry) + rotatedZ * Math.cos(ry);

  // Perspective projection
  const scale = camera.fov / (camera.fov + rotatedX + cx);
  const px = canvas.width / 2 + (rotatedY + cy) * scale;
  const py = canvas.height / 2 + (rotatedZ2 + cz) * scale;

  return [px, py];
}

// Draw a line between two 3D points
function drawLine(p1, p2) {
  const [x1, y1] = project(p1);
  const [x2, y2] = project(p2);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

// Draw the grid
function drawGrid() {
  ctx.strokeStyle = '#444';
  for (const point of gridPoints) {
    const [x, y] = project(point);
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
  }
}

// Draw the model
function drawModel() {
  ctx.strokeStyle = '#0ff';
  for (const line of model) {
    drawLine(line[0], line[1]);
  }
}

// Draw the scene
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawGrid();
  drawModel();
  requestAnimationFrame(draw);
}

// Snap point to grid
function snapToGrid(point) {
  const [x, y, z] = point;
  return [Math.round(x), Math.round(y), Math.round(z)];
}

// Handle mouse move
function handleMouseMove(e) {
  mouse.x = e.clientX;
  mouse.y = e.clientY;

  if (isDragging && selectedPoint) {
    const [x, y] = [mouse.x - canvas.width / 2, mouse.y - canvas.height / 2];
    const depth = 10; // Adjust based on camera distance
    const point = [x / depth, y / depth, -camera.fov / depth];
    selectedPoint[0] = snapToGrid(point);
  }
}

// Handle mouse down
function handleMouseDown(e) {
  const rect = canvas.getBoundingClientRect();
  const mouseX = e.clientX - rect.left;
  const mouseY = e.clientY - rect.top;

  for (let i = 0; i < model.length; i++) {
    const [p1, p2] = model[i];
    const [x1, y1] = project(p1);
    const [x2, y2] = project(p2);

    if (isNearLine(mouseX, mouseY, x1, y1, x2, y2)) {
      selectedPoint = [p1, i];
      isDragging = true;
      break;
    }
  }
}

// Check if point is near a line
function isNearLine(x, y, x1, y1, x2, y2) {
  const distance = Math.abs((y2 - y1) * x - (x2 - x1) * y + x2 * y1 - y2 * x1) / Math.sqrt((y2 - y1) ** 2 + (x2 - x1) ** 2);
  return distance < 5;
}

// Handle add line button
addLineBtn.addEventListener('click', () => {
  const startPoint = snapToGrid([mouse.x / 10, mouse.y / 10, -camera.fov / 10]);
  const endPoint = snapToGrid([(mouse.x + 50) / 10, (mouse.y + 50) / 10, -camera.fov / 10]);
  model.push([startPoint, endPoint]);
});

// Show/hide VMC menu
canvas.addEventListener('contextmenu', (e) => {
  e.preventDefault();
  vmcMenu.style.display = 'block';
  vmcMenu.style.left = `${e.clientX}px`;
  vmcMenu.style.top = `${e.clientY}px`;
});

canvas.addEventListener('click', () => {
  vmcMenu.style.display = 'none';
});

// Event listeners
canvas.addEventListener('mousemove', handleMouseMove);
canvas.addEventListener('mousedown', handleMouseDown);
canvas.addEventListener('mouseup', () => { isDragging = false; });

// Initialize and start
initGridPoints();
draw();
```

---

### **Explanation**

1. **Grid Points**: The `gridPoints` array contains all possible snapping points in a 3D grid.
2. **Projection**: The `project` function converts 3D points to 2D canvas coordinates using perspective projection and camera rotation.
3. **Drawing**: The `draw` function renders the grid and the 3D model on the canvas.
4. **Mouse Interaction**: Mouse events allow selecting and dragging points, as well as adding new lines via the VMC menu.
5. **Snapping**: Points are snapped to the grid using `snapToGrid`.

---

### **Features to Expand**
- Add rotation controls (e.g., drag to rotate the model).
- Implement zoom functionality.
- Allow deleting lines or points.
- Improve the VMC menu with more options.

This code provides a basic foundation for building a 3D wireframe constructor. You can expand it further based on your needs.

