Below is a simple BPM (Beats Per Minute) detector web application using HTML, JavaScript, and Node.js. This app uses the Web Audio API to analyze audio input from the microphone and detects the BPM in real-time.

### **index.html**
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>BPM Detector</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            text-align: center;
            margin-top: 50px;
        }
        #bpm {
            font-size: 2em;
            margin-top: 20px;
        }
        button {
            padding: 10px 20px;
            font-size: 1em;
        }
    </style>
</head>
<body>
    <h1>BPM Detector</h1>
    <button id="startButton">Start Listening</button>
    <div id="bpm">BPM: --</div>

    <script src="index.js"></script>
</body>
</html>
```

### **index.js**
```javascript
// Frontend JavaScript (this should be served by Node.js)
const startButton = document.getElementById('startButton');
const bpmDisplay = document.getElementById('bpm');

let audioContext, analyser, microphone, scriptProcessor, bpm;
const bufferLength = 1024;
const dataArray = new Uint8Array(bufferLength);

startButton.addEventListener('click', () => {
    if (!audioContext) {
        initAudio();
    } else {
        alert('Already listening. Stop and restart if needed.');
    }
});

function initAudio() {
    audioContext = new (window.AudioContext || window.webkitAudioContext)();
    analyser = audioContext.createAnalyser();
    analyser.fftSize = bufferLength * 2;

    navigator.mediaDevices.getUserMedia({ audio: true })
        .then(stream => {
            microphone = audioContext.createMediaStreamSource(stream);
            microphone.connect(analyser);
            scriptProcessor = audioContext.createScriptProcessor(bufferLength, 1, 1);
            analyser.connect(scriptProcessor);
            scriptProcessor.connect(audioContext.destination);

            scriptProcessor.onaudioprocess = () => {
                analyser.getByteTimeDomainData(dataArray);
                bpm = detectBPM(dataArray);
                bpmDisplay.textContent = `BPM: ${bpm ? bpm.toFixed(0) : '--'}`;
            };

            startButton.textContent = 'Listening...';
        })
        .catch(err => {
            console.error('Error accessing microphone:', err);
            alert('Unable to access microphone. Please allow microphone permissions.');
        });
}

function detectBPM(data) {
    let threshold = 50; // Adjust based on sensitivity
    let interval = 0;
    let lastPeak = 0;

    for (let i = 1; i < data.length; i++) {
        if (data[i] > threshold && data[i] > data[i - 1] && data[i] > data[i + 1]) {
            if (lastPeak > 0) {
                interval += i - lastPeak;
            }
            lastPeak = i;
        }
    }

    if (interval > 0 && audioContext.sampleRate) {
        const bpm = 60 / ((interval / audioContext.sampleRate) / 60);
        return bpm > 40 && bpm < 200 ? bpm : null; // Filter out unrealistic BPM values
    }
    return null;
}
```

