Uploading large files to AWS S3 from an Express.js application with chunking and progress tracking involves several steps. Below is a step-by-step guide to achieve this:

### 1. **Set Up AWS SDK and Express**
First, ensure you have the necessary dependencies installed:

```bash
npm install express aws-sdk multer multer-s3
```

### 2. **Configure AWS S3**
Set up your AWS credentials and S3 configuration:

```javascript
const AWS = require('aws-sdk');
const multer = require('multer');
const multerS3 = require('multer-s3');

AWS.config.update({
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  region: process.env.AWS_REGION,
});

const s3 = new AWS.S3();

const upload = multer({
  storage: multerS3({
    s3: s3,
    bucket: process.env.S3_BUCKET_NAME,
    contentType: multerS3.AUTO_CONTENT_TYPE,
    key: (req, file, cb) => {
      cb(null, `uploads/${Date.now()}_${file.originalname}`);
    },
  }),
});
```

### 3. **Chunked Upload with Progress Tracking**
For large files, you need to handle the upload in chunks. You can use the `aws-sdk` to manage multipart uploads and track progress.

```javascript
const express = require('express');
const app = express();

app.post('/upload', upload.single('file'), async (req, res) => {
  const file = req.file;
  const fileStream = require('fs').createReadStream(file.path);

  const params = {
    Bucket: process.env.S3_BUCKET_NAME,
    Key: file.key,
    Body: fileStream,
  };

  try {
    const uploadPromise = s3.upload(params).promise();

    uploadPromise.on('httpUploadProgress', (progress) => {
      console.log(`Uploaded ${progress.loaded} of ${progress.total} bytes`);
      // Send progress to the client if needed
      res.write(`data: ${JSON.stringify({ progress: progress.loaded / progress.total * 100 })}\n\n`);
    });

    const result = await uploadPromise;
    console.log('File uploaded successfully:', result.Location);
    res.status(200).send('File uploaded successfully');
  } catch (error) {
    console.error('Error uploading file:', error);
    res.status(500).send('Error uploading file');
  }
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

### 4. **Client-Side Progress Tracking**
To track progress on the client side, you can use the `XMLHttpRequest` or the `fetch` API with a streaming response.

Example using `fetch` with Server-Sent Events (SSE):

```javascript
const formData = new FormData();
formData.append('file', file);

const response = await fetch('/upload', {
  method: 'POST',
  body: formData,
});

const reader = response.body.getReader();
const decoder = new TextDecoder('utf-8');

while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  const progress = JSON.parse(decoder.decode(value)).progress;
  console.log(`Upload progress: ${progress}%`);
}
```

### 5. **Multipart Upload for Very Large Files**
For very large files, consider using S3's multipart upload API directly:

```javascript
const { CreateMultipartUploadCommand, UploadPartCommand, CompleteMultipartUploadCommand } = require('@aws-sdk/client-s3');

const chunkSize = 10 * 1024 * 1024; // 10MB chunks
const fileStream = require('fs').createReadStream(file.path, { highWaterMark: chunkSize });

let uploadId;
const parts = [];
let partNumber = 1;

const createMultipartUpload = async () => {
  const command = new CreateMultipartUploadCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: file.key,
  });
  const response = await s3.send(command);
  uploadId = response.UploadId;
};

const uploadPart = async (chunk) => {
  const command = new UploadPartCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: file.key,
    UploadId: uploadId,
    PartNumber: partNumber,
    Body: chunk,
  });
  const response = await s3.send(command);
  parts.push({ PartNumber: partNumber, ETag: response.ETag });
  partNumber++;
};

const completeMultipartUpload = async () => {
  const command = new CompleteMultipartUploadCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: file.key,
    UploadId: uploadId,
    MultipartUpload: { Parts: parts },
  });
  await s3.send(command);
};

fileStream.on('data', async (chunk) => {
  await uploadPart(chunk);
  console.log(`Uploaded chunk ${partNumber - 1}`);
});

fileStream.on('end', async () => {
  await completeMultipartUpload();
  console.log('Multipart upload completed');
});

await createMultipartUpload();
```

### 6. **Error Handling and Cleanup**
Ensure you handle errors and clean up incomplete uploads:

```javascript
const abortMultipartUpload = async () => {
  const command = new AbortMultipartUploadCommand({
    Bucket: process.env.S3_BUCKET_NAME,
    Key: file.key,
    UploadId: uploadId,
  });
  await s3.send(command);
};

fileStream.on('error', async (error) => {
  console.error('Error reading file:', error);
  await abortMultipartUpload();
});
```

### 7. **Environment Variables**
Store sensitive information like AWS credentials and S3 bucket name in environment variables:

```env
AWS_ACCESS_KEY_ID=your-access-key
AWS_SECRET_ACCESS_KEY=your-secret-key
AWS_REGION=your-region
S3_BUCKET_NAME=your-bucket-name
```

### Conclusion
This setup allows you to upload large files to AWS S3 in chunks while tracking the progress. The server handles the chunked upload and sends progress updates to the client. For very large files, the multipart upload approach is more efficient and reliable.

