         client.send(JSON.stringify(data));
       }
     });
   });
   ```

   В этом примере, когда приходит GET-запрос на `/api/data`, сервер отправляет ответ в формате JSON через API и одновременно отправляет те же данные всем подключенным клиентам WebSocket.

