const port = 3000;

// Middleware para parsear JSON
app.use(express.json());

// Datos de ejemplo (en un entorno real, usarías una base de datos)
let usuarios = [
  { id: 1, nombre: 'Juan', edad: 30 },
  { id: 2, nombre: 'María', edad: 25 }
];

