```javascript
function applyStylesAndRemoveTags(text) {
    // Define a mapping of HTML tags to their CSS styles
    const tagStyles = {
        'b': 'font-weight: bold;',
        'i': 'font-style: italic;',
        'u': 'text-decoration: underline;'
    };

    // Use a regular expression to find all HTML tags in the text
    const tagRegex = /<(\/?)(b|i|u)>/g;
    let match;
    let styles = [];

    // Collect all opening tags and their corresponding styles
    while ((match = tagRegex.exec(text)) !== null) {
        if (!match[1] && tagStyles[match[2]]) { // If it's an opening tag
            styles.push(tagStyles[match[2]]);
        } else if (match[1] && styles.length > 0) { // If it's a closing tag
            styles.pop();
        }
    }

    // Combine all collected styles into a single style string
    const combinedStyles = styles.join(' ');

    // Remove all HTML tags from the text
    const cleanText = text.replace(/<\/?(b|i|u)>/g, '');

    // Wrap the cleaned text with a <span> element and apply the combined styles
    return `<span style="${combinedStyles}">${cleanText}</span>`;
}

// Example usage:
const inputText = '<b><i>My test text</i></b>';
const styledText = applyStylesAndRemoveTags(inputText);
console.log(styledText); // Output: <span style="font-weight: bold; font-style: italic;">My test text</span>
```

