```

### 3. Traverse the AST
Once the project is loaded, you can traverse the AST of each source file.

```typescript
sourceFiles.forEach(sourceFile => {
  // Start traversing from the root node (source file)
  traverseNode(sourceFile);
});

function traverseNode(node: Node) {
  // Process the current node
  console.log(`Node kind: ${node.getKindName()}, Text: ${node.getText()}`);

  // Recursively traverse child nodes
  node.forEachChild(child => {
    traverseNode(child);
  });
}
