    console.log(`Variable name: ${variableDeclaration.getName()}`);
  }

  node.forEachChild(child => {
    traverseNode(child);
  });
}
```

### 5. Full Example
Here’s a complete example that loads a project, traverses the AST, and logs variable declarations:

```typescript
