Oto przykładowy kod w Node.js, który szyfruje plik (np. `plik.js`) przy użyciu algorytmu AES-256-CBC. Do tego celu wykorzystamy wbudowany moduł `crypto`.

```javascript
const fs = require('fs');
const crypto = require('crypto');

// Klucz szyfrowania (musi mieć długość 32 bajtów dla AES-256-CBC)
const encryptionKey = 'moj_tajny_klucz_1234567890123456'; // Zastąp swoim kluczem

// Wektor inicjalizacyjny (IV) - powinien być unikalny dla każdego szyfrowania
const iv = crypto.randomBytes(16);

// Funkcja do szyfrowania pliku
function encryptFile(inputFilePath, outputFilePath) {
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionKey), iv);

    const input = fs.createReadStream(inputFilePath);
    const output = fs.createWriteStream(outputFilePath);

    // Zapisz IV na początku zaszyfrowanego pliku, aby można było go później odszyfrować
    output.write(iv);

    // Przepływ danych: plik wejściowy -> cipher -> plik wyjściowy
    input.pipe(cipher).pipe(output);

    output.on('finish', () => {
        console.log(`Plik ${inputFilePath} został zaszyfrowany i zapisany jako ${outputFilePath}`);
    });
}

// Użycie funkcji
