Implementing column filtering and global search filtering in a grid (typically a data grid or table) involves both frontend and backend logic. Below is a general guide on how to achieve this using a common frontend framework like React and a backend framework like Node.js with Express. I'll also provide a basic example using a library like **React Table** for the frontend and a simple backend API.

---

### **Frontend Implementation (React with React Table)**

#### 1. **Install Dependencies**
```bash
npm install react-table @tanstack/react-table
```

#### 2. **Basic Grid Component with Filtering**
```jsx
import React, { useState, useMemo } from "react";
import { useTable, useFilters, useGlobalFilter } from "react-table";

// Sample data
const data = [
  { id: 1, name: "John Doe", age: 30, city: "New York" },
  { id: 2, name: "Jane Smith", age: 25, city: "Los Angeles" },
  { id: 3, name: "Sam Green", age: 35, city: "Chicago" },
];

// Column definitions
const columns = [
  { Header: "ID", accessor: "id" },
  { Header: "Name", accessor: "name" },
  { Header: "Age", accessor: "age" },
  { Header: "City", accessor: "city" },
];

const Table = () => {
  const [globalFilter, setGlobalFilter] = useState("");

  const {
    getTableProps,
    getTableBodyProps,
    headerGroups,
    rows,
    prepareRow,
    setFilter,
    state,
  } = useTable(
    {
      columns,
      data,
    },
    useFilters,
    useGlobalFilter
  );

  const { globalFilter: globalFilterState } = state;

  // Global filter function
  const handleGlobalFilterChange = (e) => {
    const value = e.target.value || undefined;
    setGlobalFilter(value);
  };

  // Column filter function
  const handleColumnFilterChange = (columnId, value) => {
    setFilter(columnId, value || undefined);
  };

  return (
    <div>
      {/* Global Search */}
      <input
        type="text"
        value={globalFilterState || ""}
        onChange={handleGlobalFilterChange}
        placeholder="Global Search"
      />

      <table {...getTableProps()}>
        <thead>
          {headerGroups.map((headerGroup) => (
            <tr {...headerGroup.getHeaderGroupProps()}>
              {headerGroup.headers.map((column) => (
                <th {...column.getHeaderProps()}>
                  {column.render("Header")}
                  {/* Column Filter */}
                  <input
                    type="text"
                    value={column.filterValue || ""}
                    onChange={(e) =>
                      handleColumnFilterChange(column.id, e.target.value)
                    }
                    placeholder={`Filter ${column.id}`}
                  />
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody {...getTableBodyProps()}>
          {rows.map((row) => {
            prepareRow(row);
            return (
              <tr {...row.getRowProps()}>
                {row.cells.map((cell) => (
                  <td {...cell.getCellProps()}>{cell.render("Cell")}</td>
                ))}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

export default Table;
```

