### **Backend Implementation (Node.js with Express)**

If you need to handle filtering on the backend (e.g., for large datasets), you can create an API endpoint that accepts filter parameters.

#### 1. **Install Dependencies**
```bash
npm install express mongoose
```

#### 2. **Backend API for Filtering**
```javascript
const express = require("express");
const mongoose = require("mongoose");
const app = express();
const port = 3000;

// Connect to MongoDB (replace with your connection string)
mongoose.connect("mongodb://localhost:27017/testdb", {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Sample Schema
const userSchema = new mongoose.Schema({
  name: String,
  age: Number,
  city: String,
});

const User = mongoose.model("User", userSchema);

// Middleware
app.use(express.json());

// Filtering endpoint
app.get("/users", async (req, res) => {
  const { name, age, city, search } = req.query;

  let query = {};

  // Global search
  if (search) {
    query = {
      $or: [
        { name: { $regex: search, $options: "i" } },
        { city: { $regex: search, $options: "i" } },
      ],
    };
  }

  // Column filters
  if (name) query.name = { $regex: name, $options: "i" };
  if (age) query.age = parseInt(age);
  if (city) query.city = { $regex: city, $options: "i" };

  try {
    const users = await User.find(query);
    res.json(users);
  } catch (error) {
    res.status(500).json({ message: "Server error" });
  }
});

app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
```

