### 1. Установите необходимые зависимости
```bash
npm install express sqlite3
```

### 2. Создайте файл (например, `server.js`) с следующим кодом:

```javascript
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const app = express();
const port = 3000;

// Подключение к базе данных (или создание новой)
const db = new sqlite3.Database('./database.sqlite', (err) => {
  if (err) {
    console.error('Ошибка подключения к базе данных:', err.message);
  } else {
    console.log('Подключено к базе данных SQLite');

    // Создание таблицы пользователей (если не существует)
    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        email TEXT NOT NULL
      )
    `);
  }
});

// Middleware для парсинга JSON
app.use(express.json());

// Маршрут для получения пользователя по ID
app.get('/user/:id', (req, res) => {
  const userId = req.params.id;

  // SQL-запрос для получения пользователя
  const query = 'SELECT * FROM users WHERE id = ?';

  db.get(query, [userId], (err, row) => {
    if (err) {
      return res.status(500).json({ error: err.message });
    }
    if (!row) {
      return res.status(404).json({ message: 'Пользователь не найден' });
    }
    res.json(row); // Возвращаем строку пользователя
  });
});

// Запуск сервера
app.listen(port, () => {
  console.log(`Сервер запущен на http://localhost:${port}`);
});
```

### 3. Пример использования:
