```javascript
function transformArrayToObject(arr) {
    const result = {};
    let current = result;
    let path = [];

    function processElement(element, isArray) {
        if (isArray) {
            const key = path[path.length - 1];
            current[key] = element.map(item => typeof item === 'string' ? item : processElement(item, true));
        } else {
            if (typeof element === 'string') {
                path.push(element);
                current[element] = {};
                const newCurrent = current;
                current = current[element];
                if (path.length > 1) {
                    const parentKey = path[path.length - 2];
                    if (Array.isArray(newCurrent[parentKey])) {
                        newCurrent[parentKey].push(current);
                    }
                }
            } else if (Array.isArray(element)) {
                processElement(element, true);
            }
        }
    }

    arr.forEach(element => {
        processElement(element, Array.isArray(element));
    });

    return result;
}

// Пример использования
const input = [
    "DCU_DLMS",
    "Parameters",
    "General",
    "Read",
    ["Get Version", "Get Date & Time"],
    "Write",
