document.getElementById('calculate').addEventListener('click', () => {
    const a = parseInt(document.getElementById('a').value, 10);
    const b = parseInt(document.getElementById('b').value, 10);
    const resultDiv = document.getElementById('result');

    if (isNaN(a) || isNaN(b) || a <= 0 || b <= 0) {
        resultDiv.textContent = 'Vui lòng nhập hai số nguyên dương hợp lệ.';
        return;
    }

    const steps = extendedGCD(a, b);
    const inverse = steps[0];
    const isValid = steps[1];

    if (!isValid) {
        resultDiv.textContent = `Không tồn tại nghịch đảo của ${a} modulo ${b}.`;
        return;
    }

    let output = '';
    for (let i = 1; i < steps[2].length; i++) {
        output += steps[2][i] + '\n';
    }

    output += `\n=> ${a}^-1 (mod ${b}) = ${(inverse % b + b) % b}\n`;

    resultDiv.textContent = output;
});

function extendedGCD(a, b) {
    const steps = [];
    let x = 0, y = 1, u = 1, v = 0;
    while (a !== 0) {
        const q = Math.floor(b / a);
        const r = b % a;
        const m = x - u * q;
        const n = y - v * q;
        steps.push(`${b} = ${q} * ${a} + ${r}`);
        b = a;
        a = r;
        x = u;
        y = v;
        u = m;
        v = n;
    }

    if (b === 1) {
        let result = '';
        let tempX = x;
        let tempY = y;
        for (let i = steps.length - 1; i >= 0; i--) {
            const [lhs, rhs] = steps[i].split(' = ');
            const [q, a, r] = rhs.split(' * ').concat(rhs.split(' + ').pop());
            if (i === steps.length - 1) {
                result = `1 = ${tempX} * ${lhs} + ${tempY} * ${a}`;
            } else {
                const prevLhs = steps[i + 1].split(' = ')[0];
                const prevX = tempX - parseInt(q, 10) * parseInt(tempY, 10);
                result = `${tempX} = ${prevX} * ${prevLhs} + ${tempY} * ${a}`;
                tempX = prevX;
            }
            steps[i] = result;
        }

        return [x, true, steps];
    } else {
        return [0, false, []];
    }
}
