/**
 * Manages WebSocket connections and handles message events.
 * @class
 */
class WebSocketManager {
  /**
   * Initializes a new instance of WebSocketManager.
   * Sets up an event emitter for handling WebSocket events.
   */
  constructor() {
    this.emitter = mitt()
  }

  /**
   * Opens a WebSocket connection to the specified server.
   * Listens for incoming messages and emits events based on the message type.
   */
  open() {
    this.socket = new WebSocket('ws://owbalancer.ddns.net:8765/site')
    const self = this
    this.socket.addEventListener('message', (msg) => {
      const json = JSON.parse(msg.data)
      const { action, uuid, factory, inventory } = json

      // Emit events based on the action type
      if (action === 'update_station') self.emitter.emit('update_station', { uuid })
      if (action === 'update_station_list') self.emitter.emit('update_station_list')
      if (action === 'update_inventory') {
        self.emitter.emit('update_inventory', {
          factory_uuid: factory,
          inventory_name: inventory
        })
      }
    })
  }

  /**
   * Sends a message over the WebSocket connection.
   * @param {Object} data - The data to be sent as a JSON string.
   */
  sendMessage(data) {
    this.socket.send(JSON.stringify(data))
  }
}

/**
 * Singleton instance of WebSocketManager for global use.
 * @type {WebSocketManager}
 */
export const websocketApi = new WebSocketManager()
