    input: process.stdin,
    output: process.stdout
});

// Function to ask for user input
function askQuestion(query) {
    return new Promise(resolve => rl.question(query, resolve));
}

// Function to parse SQL schema and extract table details
function parseSqlSchema(schema) {
    const ast = parse(schema);
    const table = ast.stmt[0].table;
    const columns = table.columns.map(col => ({
        name: col.column,
        type: col.type,
        constraints: col.constraints || []
    }));
    return {
        tableName: table.name,
        columns
    };
}

// Function to generate files using EJS templates
async function generateFiles(tableDetails, outputDir) {
    const templatesDir = path.join(__dirname, 'templates');
    const filesToGenerate = [{
        template: 'model.ejs',
        output: `${tableDetails.tableName}.model.js`
    }, {
        template: 'controller.ejs',
        output: `${tableDetails.tableName}.controller.js`
    }, {
        template: 'router.ejs',
        output: `${tableDetails.tableName}.router.js`
    }];

    if (!fs.existsSync(outputDir)) {
        fs.mkdirSync(outputDir);
    }

    for (const file of filesToGenerate) {
        const templatePath = path.join(templatesDir, file.template);
        const outputPath = path.join(outputDir, file.output);
        const template = fs.readFileSync(templatePath, 'utf-8');
        const rendered = ejs.render(template, {
            table: tableDetails
        });
        fs.writeFileSync(outputPath, rendered);
    }

