В рамках веб-приложения на Express.js с использованием Node.js и SQLite3, авторизация пользователя может быть реализована с помощью контроллеров (controllers) и моделей (models). Ниже приведен пример, как это можно сделать.

### Структура проекта
```
/project
  /controllers
    AuthController.js
  /models
    UserModel.js
  /routes
    AuthRoutes.js
  app.js
  package.json
```

### 1. Модель пользователя (UserModel.js)
Модель отвечает за взаимодействие с базой данных.

```javascript
// models/UserModel.js
const sqlite3 = require('sqlite3').verbose();
const db = new sqlite3.Database('database.sqlite');

class UserModel {
  static async findByUsername(username) {
    return new Promise((resolve, reject) => {
      db.get('SELECT * FROM users WHERE username = ?', [username], (err, row) => {
        if (err) reject(err);
        resolve(row);
      });
    });
  }

  static async createUser(username, passwordHash) {
    return new Promise((resolve, reject) => {
      db.run('INSERT INTO users (username, password_hash) VALUES (?, ?)', [username, passwordHash], function(err) {
        if (err) reject(err);
        resolve(this.lastID);
      });
    });
  }
}

module.exports = UserModel;
```

### 2. Контроллер авторизации (AuthController.js)
Контроллер обрабатывает логику авторизации.

```javascript
// controllers/AuthController.js
const UserModel = require('../models/UserModel');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

class AuthController {
  static async register(req, res) {
    const { username, password } = req.body;
    const passwordHash = await bcrypt.hash(password, 10);
    try {
      const userId = await UserModel.createUser(username, passwordHash);
      res.status(201).json({ message: 'User created', userId });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  }

  static async login(req, res) {
    const { username, password } = req.body;
    try {
      const user = await UserModel.findByUsername(username);
      if (!user) return res.status(404).json({ message: 'User not found' });

      const isMatch = await bcrypt.compare(password, user.password_hash);
      if (!isMatch) return res.status(401).json({ message: 'Invalid credentials' });

      const token = jwt.sign({ userId: user.id }, 'your_secret_key', { expiresIn: '1h' });
      res.json({ token });
    } catch (err) {
      res.status(500).json({ error: err.message });
    }
  }
}

module.exports = AuthController;
```

### 3. Маршруты авторизации (AuthRoutes.js)
Маршруты связывают HTTP-запросы с методами контроллера.

```javascript
// routes/AuthRoutes.js
const express = require('express');
const router = express.Router();
const AuthController = require('../controllers/AuthController');

router.post('/register', AuthController.register);
router.post('/login', AuthController.login);

module.exports = router;
```

### 4. Haupt-Datei (app.js)
Главная точка входа приложения, где настраивается сервер и подключаются маршруты.

```javascript
// app.js
const express = require('express');
const bodyParser = require('body-parser');
const authRoutes = require('./routes/AuthRoutes');

const app = express();
const PORT = 3000;

app.use(bodyParser.json());
app.use('/auth', authRoutes);

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

### Пояснение:
- **Модель (UserModel)**: Отвечает за взаимодействие с базой данных SQLite3. Метод `findByUsername` ищет пользователя по имени, а `createUser` создает нового пользователя.
- **Контроллер (AuthController)**: Содержит бизнес-логику для регистрации и авторизации пользователей. Использует `bcrypt` для хеширования паролей и `jsonwebtoken` для генерации JWT-токенов.
- **Маршруты (AuthRoutes)**: Определяют эндпоинты `/register` и `/login`, которые вызывают соответствующие методы контроллера.

### Пример запросов:
**Регистрация:**
```bash
curl -X POST -H "Content-Type: application/json" -d '{"username": "testuser", "password": "testpassword"}' http://localhost:3000/auth/register
```

**Авторизация:**
```bash
curl -X POST -H "Content-Type: application/json" -d '{"username": "testuser", "password": "testpassword"}' http://localhost:3000/auth/login
```

Этот пример демонстрирует, как контроллеры и модели взаимодействуют для реализации авторизации пользователя в приложении на Express.js с использованием SQLite3.

