let resultChart = null;

function calculateMarkup() {
  const cost = parseFloat(document.getElementById('cost').value);
  const markup = parseFloat(document.getElementById('markup').value);

  if (isNaN(cost) || isNaN(markup)) {
    alert('Please enter valid numbers for cost and markup.');
    return;
  }

  const sellingPrice = cost * (1 + markup / 100);
  const profit = sellingPrice - cost;
  const margin = (profit / sellingPrice) * 100;

  document.getElementById('sellingPrice').textContent = sellingPrice.toFixed(2);
  document.getElementById('profit').textContent = profit.toFixed(2);
  document.getElementById('margin').textContent = margin.toFixed(2);

  updateChart(cost, profit, sellingPrice);
}

function updateChart(cost, profit, sellingPrice) {
  const ctx = document.getElementById('resultChart').getContext('2d');

  if (resultChart) {
    resultChart.destroy();
  }

  resultChart = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: ['Cost', 'Profit', 'Selling Price'],
      datasets: [{
        label: 'Amount',
        data: [cost, profit, sellingPrice],
        backgroundColor: ['#17a2b8', '#28a745', '#007bff'],
      }]
    },
    options: {
      scales: {
        y: {
          beginAtZero: true
        }
      }
    }
  });
}
