        const recordIdList = this.recordIds.split(',').map(id => id.trim());
        const formData = new FormData();
        formData.append('file', this.file);
        formData.append('recordIds', JSON.stringify(recordIdList));

        uploadDocument({ formData })
            .then(() => {
                this.dispatchEvent(new CustomEvent('close'));
                // Show success message
                showToast('Success', 'Document attached successfully!', 'success');
            })
            .catch(error => {
                console.error('Error uploading document:', error);
                // Show error message
                showToast('Error', 'Failed to attach document.', 'error');
            });
    }

    handleCancel() {
        this.dispatchEvent(new CustomEvent('close'));
    }
