import { fromEvent, ajax } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';

// DOM Elements
const showDataBtn = document.getElementById('showDataBtn')!;
const deleteBtn = document.getElementById('deleteBtn')!;
const dataBody = document.getElementById('dataBody')!;

// Event Observables
const showDataClick$ = fromEvent(showDataBtn, 'click');
const deleteClick$ = fromEvent(deleteBtn, 'click');

// Fetch data from server
const fetchData$ = showDataClick$.pipe(
    switchMap(() => ajax.getJSON('https://jsonplaceholder.typicode.com/users'))
);

// Add data to table
fetchData$.subscribe((data: any[]) => {
    data.forEach((item: any) => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.id}</td>
            <td>${item.name}</td>
            <td>${item.email}</td>
        `;
        dataBody.appendChild(row);
    });
});

// Delete last row
deleteClick$.subscribe(() => {
    const rows = dataBody.getElementsByTagName('tr');
    if (rows.length > 0) {
        dataBody.removeChild(rows[rows.length - 1]);
    }
});
```

