function getCoordinates(cellId) {
  const col = cellId.charCodeAt(0) - 'a'.charCodeAt(0);
  const row = 8 - parseInt(cellId[1], 10);
  return [row, col];
}

// Check if cell is empty
function isEmpty(cellId) {
  const cell = document.getElementById(cellId);
  return !cell.firstChild;
}

// Check if cell contains an enemy piece
function isEnemyPiece(cellId, color) {
  const cell = document.getElementById(cellId);
  if (!cell.firstChild) return false;
  const pieceColor = cell.firstChild.id.split('-')[2];
  return pieceColor !== color;
}

// Generate rook moves
function generateRookMoves(startId, color) {
  const [row, col] = getCoordinates(startId);
  const moves = [];

  // Directions: up, down, left, right
  const directions = [
    [-1, 0], [1, 0], [0, -1], [0, 1]
  ];

  for (const [dr, dc] of directions) {
    for (let i = 1; i < 8; i++) {
      const r = row + dr * i;
      const c = col + dc * i;
      if (!isInBounds(r, c)) break;
      const cellId = getCellId(r, c);
      if (isEmpty(cellId)) {
        moves.push(cellId);
      } else if (isEnemyPiece(cellId, color)) {
        moves.push(cellId);
        break;
      } else {
        break;
      }
    }
  }

  return moves;
}

// Generate knight moves
function generateKnightMoves(startId, color) {
  const [row, col] = getCoordinates(startId);
  const moves = [];

  // Knight's L-shaped moves
  const knightMoves = [
    [-2, -1], [-2, 1], [2, -1], [2, 1],
    [-1, -2], [-1, 2], [1, -2], [1, 2]
  ];

  for (const [dr, dc] of knightMoves) {
    const r = row + dr;
    const c = col + dc;
    if (isInBounds(r, c)) {
      const cellId = getCellId(r, c);
      if (isEmpty(cellId) || isEnemyPiece(cellId, color)) {
        moves.push(cellId);
      }
    }
  }

  return moves;
}

// Check if coordinates are within bounds
function isInBounds(row, col) {
  return row >= 0 && row < 8 && col >= 0 && col < 8;
}

// Get a random piece of the current color
function getRandomPiece(color) {
  const pieces = Array.from(document.querySelectorAll(`[id$='-${color}']`));
  return pieces[Math.floor(Math.random() * pieces.length)].id;
}

// Generate moves for a piece based on its type
function generateMoves(pieceId, color) {
  const type = pieceId.split('-')[0];
  const moves = [];

  switch (type) {
    case 'r':
      moves.push(...generateRookMoves(pieceId, color));
      break;
    case 'n':
      moves.push(...generateKnightMoves(pieceId, color));
      break;
    // Add cases for other pieces as needed
  }

  return moves;
}

// Apply a move
function applyMove(fromId, toId) {
  const fromCell = document.getElementById(fromId);
  const toCell = document.getElementById(toId);
  toCell.innerHTML = fromCell.innerHTML;
  fromCell.innerHTML = '';
}

