const express = require('express');
const cors = require('cors');
const { Configuration, OpenAIApi } = require('openai');
require('dotenv').config();

const app = express();
const port = process.env.PORT || 3000;

app.use(cors());
app.use(express.json());
app.use(express.static('public'));

const configuration = new Configuration({
    apiKey: process.env.OPENAI_API_KEY,
});
const openai = new OpenAIApi(configuration);

app.post('/generate-quiz', async (req, res) => {
    const { board, questionType, difficultyLevel, numQuestions, additionalInfo } = req.body;

    const prompt = `Generate a radiology quiz for ${board} with ${numQuestions} ${questionType} questions at ${difficultyLevel} difficulty. Additional context: ${additionalInfo || 'None provided'}.`;

    try {
        const response = await openai.createCompletion({
            model: "text-davinci-003",
            prompt: prompt,
            max_tokens: 500,
            temperature: 0.7,
        });

        res.json({ quiz: response.data.choices[0].text.trim() });
    } catch (error) {
        console.error('Error calling OpenAI API:', error);
        res.status(500).json({ error: 'Failed to generate quiz.' });
    }
});

app.listen(port, () => {
    console.log(`Server running on http://localhost:${port}`);
});
