from .app import app, db
from flask import jsonify , abort , make_response , request, url_for

class Questionnaire(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64))
    questions = []
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return '<Questionnaire (%d) %s>' % (self.id, self.name)

    def to_json(self):
        return {
            'id': self.id,
            'name': self.name,
            'questions': [q.to_json()["url"] for q in self.questions],
            'url': url_for('get_questionnaire', id=self.id, _external=True)
        }

class Question(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(120))
    questionType = db.Column(db.String(120))
    questionnaire_id = db.Column(db.Integer, db.ForeignKey('questionnaire.id'))
    questionnaire = db.relationship('Questionnaire', backref=db.backref('questions', lazy='dynamic'))

    def __init__(self, title, questionType, questionnaire_id):
        self.title = title
        self.questionType = questionType
        self.questionnaire_id = questionnaire_id

    __mappers_args__ = {
        'polymorphic_identity': 'question',
        "with_polymorphic": "*",
        'polymorphic_on': questionType
    }

    def to_json(self):
        return {
            'id': self.id,
            'title': self.title,
            'questionType': self.questionType,
            'questionnaire_id': self.questionnaire.id,
            'url': url_for('get_question', id=self.id, _external=True)
        }

class Simple_Question(Question):
    id = db.Column(db.Integer, db.ForeignKey('question.id'), primary_key=True)
