**3. File `server.js`:**
```javascript
const express = require('express');
const axios = require('axios');
const app = express();
const port = 3000;

// YouTube Data API configuration
const API_KEY = 'YOUR_YOUTUBE_API_KEY';
const CHANNEL_ID = 'YOUR_CHANNEL_ID';
const MAX_RESULTS = 12;

app.use(express.static('public'));

app.get('/videos', async (req, res) => {
  const pageToken = req.query.pageToken || '';
  const url = `https://www.googleapis.com/youtube/v3/search?key=${API_KEY}&channelId=${CHANNEL_ID}&part=snippet&order=date&maxResults=${MAX_RESULTS}&pageToken=${pageToken}&type=video`;

  try {
    const response = await axios.get(url);
    res.json(response.data);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch videos' });
  }
});

app.listen(port, () => {
  console.log(`Server running on http://localhost:${port}`);
});
```

**4. File `public/index.html`:**
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>YouTube Video Gallery</title>
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css" rel="stylesheet">
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <div class="container mt-5">
    <h1 class="text-center mb-4">YouTube Video Gallery</h1>
    <div class="row" id="video-gallery">
      <!-- Videos will be loaded here -->
    </div>
    <nav aria-label="Pagination" id="pagination">
      <!-- Pagination will be loaded here -->
    </nav>
  </div>

  <script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script>
  <script>
    const gallery = document.getElementById('video-gallery');
    const pagination = document.getElementById('pagination');
    let nextPageToken = '';

    async function loadVideos(pageToken = '') {
      try {
        const response = await axios.get(`/videos?pageToken=${pageToken}`);
        const videos = response.data.items;
        nextPageToken = response.data.nextPageToken || '';

        gallery.innerHTML = videos.map(video => `
          <div class="col-md-4 mb-4">
            <div class="card h-100">
              <img src="${video.snippet.thumbnails.high.url}" class="card-img-top" alt="${video.snippet.title}">
              <div class="card-body">
                <h5 class="card-title">${video.snippet.title}</h5>
                <a href="https://www.youtube.com/watch?v=${video.id.videoId}" 
                   class="btn btn-primary" target="_blank">Watch Now</a>
              </div>
            </div>
          </div>
        `).join('');

        updatePagination();
      } catch (error) {
        console.error('Error fetching videos:', error);
      }
    }

    function updatePagination() {
      pagination.innerHTML = `
        <ul class="pagination justify-content-center">
          ${nextPageToken ? `<li class="page-item"><button class="page-link" onclick="loadVideos('${nextPageToken}')">Next</button></li>` : ''}
        </ul>
      `;
    }

    // Initial load
    loadVideos();
  </script>
</body>
</html>
```

**5. File `public/styles.css` (Opsional):**
```css
