### 3. **Модель базы данных (models/Database.php)**
```php
<?php
class Database
{
    protected $pdo;

    public function __construct($pdo)
    {
        $this->pdo = $pdo;
    }

    public function query($query, $params = [])
    {
        $stmt = $this->pdo->prepare($query);
        $stmt->execute($params);
        return $stmt;
    }
}
```

### 4. **Модель пользователя (models/User.php)**
```php
<?php
class User extends Database
{
    public function register($username, $password, $email)
    {
        $hashedPassword = password_hash($password, PASSWORD_DEFAULT);
        $stmt = $this->query('INSERT INTO users (username, password, email) VALUES (?, ?, ?)', [$username, $hashedPassword, $email]);
        return $stmt->rowCount() > 0;
    }

    public function login($username, $password)
    {
        $stmt = $this->query('SELECT * FROM users WHERE username = ?', [$username]);
        $user = $stmt->fetch();

        if ($user && password_verify($password, $user['password'])) {
            return $user;
        }

        return false;
    }
}
```

### 5. **Модель поста (models/Post.php)**
```php
<?php
class Post extends Database
{
    public function createPost($title, $content, $userId)
    {
        $stmt = $this->query('INSERT INTO posts (title, content, user_id) VALUES (?, ?, ?)', [$title, $content, $userId]);
        return $stmt->rowCount() > 0;
    }

    public function getPosts()
    {
        $stmt = $this->query('SELECT posts.*, users.username FROM posts JOIN users ON posts.user_id = users.id ORDER BY posts.created_at DESC');
        return $stmt->fetchAll();
    }
}
