```php
<?php
// URL видео
$videoUrl = 'https://video-cdn.aliexpress-media.com/80ffc57ef0293a3a/ae_sg_item/Bub4DyQ6ex0zl0T8ki7_1100096979227_mp4_264_sd.mp4?auth_key=1691057774-0-0-025e6559104936678796132b513c268d&w=540&h=714&e=sd&t=2141276f16832817742928523ef31f&b=ae_sg&p=ae_sg_ae_sg_vpc_scene&tr=mp4-264-sd&t_u=2141281916848399720631508e566f';

// Путь для сохранения видео на сервере
$savePath = '/path/to/save/video.mp4';

// Инициализация cURL
$ch = curl_init($videoUrl);

// Настройка опций cURL
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);

// Выполнение запроса
$videoContent = curl_exec($ch);

// Проверка на ошибки
